(window.FREALLY_I18N = window.FREALLY_I18N || {})["ar"] = {"hero.badge":"الإصدار 1.5.0 هو الإصدار الحالي","hero.headline":"<span class=\"hl-muted\">اظهر بثقة.</span> <span class=\"hl-bright\">والتزم بالنص.</span>","hero.sub":"ملقّن نصوص لحاسوبك يقرأ بوتيرة بشرية حقيقية — بالأحرف في الثانية، أو بـ BPM مقطوعتك — ويُبرز كل وقفة تكتبها في النص.","hero.chipDesktop":"تطبيق لسطح المكتب","hero.chipLanguages":"18 لغة","hero.chipNoAccount":"بلا حساب","what.is.title":"ما هو","what.is.lead":"قراءة نص أمام الكاميرا تعني عادةً تمريرًا أسرع أو أبطأ مما ينبغي، ووقفة نسيتها، وشاشة ثانية متأخرة بسطر.","what.is.body":"Freally Teleprompt جهاز تلقين لحاسوبك. افتح النص الذي أُرسل إليك، واضبط السرعة بالأحرف في الثانية أو على BPM مقطوعتك، فيقرأ بسرعة بشرية حقيقية — كل وقفة كتبتها معلَّمة في النص، وكل شاشة على الكلمة نفسها.","what.title":"ما الذي يفعله","features.pace.title":"وتيرة قراءة حقيقية","features.pace.body":"اضبط السرعة بالأحرف في الثانية، أو بـ BPM من 20 إلى 250 لتقرأ في تزامن مع مقطوعة — لا بمؤشر اعتباطي من 1 إلى 10.","features.pauses.title":"وقفات تراها","features.pauses.body":"اكتب -- لوقفة قصيرة أو ‎--3 لتوقّف مدته ثلاث ثوانٍ. تصبح كلٌّ منها شارة في المحرر، وتُضاء حين تصل إليها القراءة.","features.screens.title":"كل الشاشات على الكلمة نفسها","features.screens.body":"محرّك واحد، يعدّ بالأحرف، يدير معاينتك وجهاز عرض المقدّم — مقلوبًا لزجاج التلقين إن احتجت إلى ذلك — والهواتف على شبكتك أنت، فلا تتباعد أبدًا.","features.import.title":"افتح الملف الذي أُرسل إليك","features.import.body":"استورد ملفات Word وRTF وPDF والنص العادي وMarkdown كنص ملقّن نظيف، مع تقرير بكل ما تعذّر نقله.","features.markers.title":"اعثر على طريقك في النص","features.markers.body":"السطر الذي يبدأ بـ # يصبح علامة قسم في قائمة انتقال، إلى جانب البحث والاستبدال وعدّ الكلمات المباشر.","features.timing.title":"اقرأ وفق التوقيت","features.timing.body":"انقر إيقاعك أنت، واسمع نقرة المترونوم مع عدّ تمهيدي، وشاهد المازورات والضربات، وتدرّب لتحصل على تقرير توقيت قسمًا قسمًا.","features.control.title":"دواسات وأجهزة تحكم ومفاتيح عامة","features.control.body":"لكل أمر مفتاح يمكنك تغييره. تُعيَّن دواسات القدم وأجهزة التحكم عن بُعد للعروض التقديمية كأي مفتاح، ويمكن لمفتاح أن يعمل حتى حين لا يكون التطبيق في المقدمة.","features.writing.title":"عون أثناء الكتابة","features.writing.body":"إكمال تلقائي بـ 18 لغة من قوائم كلمات داخل التطبيق، وإملاء بالإنجليزية: قُلها، فتُكتب في النص.","features.private.title":"ملكك، على حاسوبك","features.private.body":"بلا حساب، ولا قياس عن بُعد، ولا سحابة. النصوص ملفات عادية على حاسوبك، ولا يسأل التطبيق الإنترنت إلا عن شيء واحد: هل يوجد إصدار أحدث.","ladder.title":"الطريق إلى 2.0","ladder.intro":"كل إصدار حتى الآن، ثم الخطوات المخطط لها في الطريق إلى 2.0. تحصل الخطوة على رقم إصدارها حين تصدر، والخطة قابلة للتغيير.","ladder.rung.v0.100.0":"الأساس: يعمل التطبيق على Windows وmacOS وLinux، ويطلب منك قبول ترخيصه، ويمرّر النص بالمحرّك القائم على الأحرف المأخوذ من Freally Capture.","ladder.rung.v0.200.0":"الملقّن المستقل: مكتبة للنصوص، وشارات للوقفات، وجهاز عرض للمقدّم مع قلب مرآوي، ومزامنة مع الهواتف على شبكتك أنت، وأزرار تشغيل حقيقية، وضبط الوتيرة بـ BPM، والقراءة بصوت عالٍ.","ladder.rung.v0.300.0":"إكمال تلقائي دون اتصال: يُكمل الكلمات والعبارات الشائعة وأنت تكتب، باللغات الثماني عشرة كلها، من قوائم كلمات داخل التطبيق.","ladder.rung.v1.0.0":"أول إصدار كامل: جولة ترحيبية مدتها دقيقة، وتحسينات لدعم لوحة المفاتيح وقارئات الشاشة، وسمة تتبع نظامك، وتحديثات لا تُثبَّت إلا بعد موافقتك.","ladder.rung.v1.1.0":"اكتب نصك بالكلام: إملاء يعمل على حاسوبك، دون أي شيء يحتاج إلى تدريب.","ladder.rung.v1.2.0":"الإملاء مكتملًا: زر تسجيل حقيقي، وكلمات تحطّ حيث يكون مؤشرك، وتراجع يستعيد شيئًا واحدًا قلته.","ladder.rung.v1.3.0":"القراءة وفق التوقيت: إيقاع تنقره ليطابق أداءك، ومترونوم، وعدّاد للمازورات والضربات، وتدريب مع تقرير للتوقيت، وتسميات لا تستهلك شيئًا من زمن القراءة.","ladder.rung.v1.4.0":"إدخال النص: استيراد ملفات Word وRTF وPDF والنص وMarkdown، وعلامات أقسام مع قائمة انتقال، والبحث والاستبدال، وإحصاءات النص.","ladder.rung.v1.5.0":"أي شيء في الغرفة يمكنه التحكم فيه: دواسات القدم وأجهزة التحكم عن بُعد للعروض التقديمية، ومفاتيح تعمل حين لا يكون التطبيق في المقدمة، وخريطة لكل الأوامر قابلة لإعادة التعيين.","ladder.rung.rig":"مصمَّم لعُدّة التصوير: قلب عمودي لزجاج التلقين العلوي، وأدلة للعدسة والهوامش الآمنة، وعرض للزمن المنقضي والمتبقي، وإعدادات مسبقة للقراءة من مسافة.","ladder.rung.takes":"لا تفقد أي لقطة: استعادة التعديلات غير المحفوظة بعد التعطّل، وإعدادات تنتقل مع كل نص، وسجل محلي للنُّسخ، وتصدير إلى PDF لنسخة احتياطية ورقية.","ladder.rung.writing":"عون في الكتابة: باحث عن القوافي، وعدد المقاطع الصوتية لكل سطر، وفحص للعبارات العسيرة النطق، ووقفات مقترحة — من القواميس، دون أي نموذج.","ladder.rung.remote":"تحكّم فيه من أي مكان: صفحة تحكم بحجم الهاتف، إضافةً إلى MIDI وOSC لطاولة التحكم التي تديرها أصلًا — على شبكتك أنت فقط، ومعطّلة افتراضيًا.","ladder.rung.show":"أدِر عرضًا كاملًا: جداول سير البرنامج مع مدة لكل فقرة، وأكثر من مخرج واحد للملقّن، وشاشة كبيرة للعدّ التنازلي وأضواء الإشارة لأرضية الاستوديو.","ladder.rung.record":"سجّل وأنت تقرأ من الملقّن: لقطة بكاميرا الويب أثناء تشغيل النص، أو صوت فقط مع كتابة علامات أقسامك في الملف كفصول.","ladder.rung.languages":"كل نص، بكل لغة: إبراز الكلمات المفردة، وحروف الفوريغانا فوق السطر، وتحسينات الكتابة من اليمين إلى اليسار للعربية، والكتابة العمودية لليابانية والصينية.","ladder.rung.v2.0.0":"الإصدار 2.0: كل ما سبق، على Windows وmacOS وLinux.","ladder.note":"«منجز» يعني أنه صدر ووُسم. ومع ذلك، لا يقدّم هذا الموقع أي تنزيلات.","honest.title":"الأشياء التي تضعها معظم المواقع في الأسفل","honest.model.title":"الإملاء يستخدم نموذج كلام","honest.model.body":"الإملاء هو الجزء الوحيد من التطبيق الذي يستخدم تعلّم الآلة: Vosk، وهو محرّك مفتوح المصدر للتعرّف على الكلام، مع نموذج إنجليزي صغير حجمه نحو 40 ميغابايت داخل التطبيق. يعمل على حاسوبك، ولا يرفع شيئًا ولا يُنزّل شيئًا، ولا يفهم إلا الإنجليزية، ويبقى معطّلًا حتى تفعّله. وكل ما عدا ذلك شيفرة عادية وقوائم كلمات.","honest.update.title":"يطرح على الإنترنت سؤالًا واحدًا","honest.update.body":"في كل مرة يبدأ فيها التطبيق، يسأل GitHub هل يوجد إصدار أحدث. لا يحمل الطلب أي نص ولا أي إعدادات ولا أي معرّف، ولا يُثبَّت شيء ما لم توافق. وكل ما عدا ذلك يعمل دون أي اتصال على الإطلاق.","honest.voice.title":"لا يتتبّع صوتك","honest.voice.body":"بعض أجهزة التلقين تمرّر النص بالاستماع إليك وأنت تقرأ. أما Freally Teleprompt 1.5.0 فيمرّره بالوتيرة التي تضبطها، وتتولى أنت أو مفتاح أو دواسة التحكم حين تتغيّر القراءة. جُرّب وضع لتتبّع الصوت في 1.0.0 وأُزيل في 1.1.0.","honest.downloads.title":"لا توجد تنزيلات على هذا الموقع","honest.downloads.body":"لا رابط تنزيل، ولا زر، ولا نسخة تجريبية. والشيفرة المصدرية خاصة أيضًا.","site.tagline":"اظهر بثقة. والتزم بالنص.","footer.licence":"ملكية خاصة — جميع الحقوق محفوظة. © Mike Weaver. الاستخدام مجاني اليوم؛ وقد تُباع الإصدارات المستقبلية. ليس مفتوح المصدر.","footer.yours":"نصوصك ملكك. تبقى على حاسوبك، ولا يتلقاها مؤلف التطبيق ولا يخزّنها ولا يمرّرها أبدًا.","featuresPage.lead":"ملقّن نصوص لـ Windows وmacOS وLinux يقرأ بوتيرة بشرية حقيقية، ويُبقي كل الشاشات على الكلمة نفسها، ويفتح النص الذي أُرسل إليك.","featuresPage.version":"تصف هذه الصفحة Freally Teleprompt 1.5.0، الإصدار المنشور: كل ما فيها موجود في 1.5.0، ولا شيء مما لا يزال مخططًا له مذكور فيها.","featuresPage.numbers.intro":"كل رقم هنا هو ما يفعله الإصدار 1.5.0، معدودًا من شيفرته. لا شيء مقرَّب إلى الأعلى.","featuresPage.numbers.paces":"طرق لضبط الوتيرة: الأحرف في الثانية أو BPM","featuresPage.numbers.bpm":"BPM: النطاق الذي يقرأ فيه على إيقاع","featuresPage.numbers.formats":"أنواع من الملفات يستوردها: Word وRTF وPDF والنص العادي وMarkdown","featuresPage.numbers.systems":"أنظمة تشغيل: Windows وmacOS وLinux","featuresPage.numbers.languages":"لغة، في التطبيق وفي إكماله التلقائي","featuresPage.numbers.words":"كلمة في قوائم إكماله التلقائي، مع 344,891 عبارة","featuresPage.numbers.accounts":"حسابات يلزمك إنشاؤها","featuresPage.numbers.model":"نموذج كلام، للإملاء: على حاسوبك، ومعطّل حتى تفعّله","featuresPage.numbers.price":"السعر اليوم","featuresPage.free.title":"مجاني اليوم","featuresPage.free.body":"كل ما يفعله Freally Teleprompt 1.5.0 مجاني اليوم، للجميع: لا فئة مدفوعة، ولا اشتراك، ولا حساب، ولا فترة تجريبية تنتهي.","featuresPage.cards.title":"ما يفعله الإصدار 1.5.0","featuresPage.cards.pace.title":"وتيرة قراءة حقيقية","featuresPage.cards.pace.body":"أحرف في الثانية، أو BPM من 20 إلى 250 لكلمات الأغاني والمقاطع التي تُقرأ على مقطوعة. غيّر أيًّا منهما أثناء تشغيل النص فيعيد التمرير ضبط وتيرته فورًا.","featuresPage.cards.pauses.title":"شارات الوقفات","featuresPage.cards.pauses.body":"اكتب -- لوقفة قصيرة أو ‎--N لتوقّف مدته N ثانية. كلٌّ منها شارة واحدة لا يستطيع المؤشر تقسيمها، تُضاء حين تصل إليها القراءة، وتحوّلها القراءة بصوت عالٍ إلى صمت حقيقي.","featuresPage.cards.engine.title":"كل الشاشات على الكلمة نفسها","featuresPage.cards.engine.body":"تتبع المعاينة وجهاز العرض والأجهزة على شبكتك محرّكًا واحدًا يعدّ بالأحرف، فتتفق على الكلمة التي تُقرأ حتى بأحجام نص مختلفة.","featuresPage.cards.projector.title":"جهاز عرض للمقدّم","featuresPage.cards.projector.body":"ملء الشاشة على أي شاشة عرض، معكوسًا لزجاج مقسّم الأشعة، مع أزرار تشغيل ومفاتيح خاصة به لمن يقرأ.","featuresPage.cards.mirror.title":"مزامنة مع الهواتف والأجهزة اللوحية","featuresPage.cards.mirror.body":"معطّلة حتى تفعّلها. يفتح رابط ورمز QR النص في أي متصفح على شبكتك أنت: للقراءة فقط، بمفتاح يتغيّر في كل مرة يبدأ فيها التطبيق.","featuresPage.cards.import.title":"استيراد Word وRTF وPDF والنص وMarkdown","featuresPage.cards.import.body":"نص ملقّن نظيف تُحفظ فقراته، وتقرير يعدّ ما تعذّر نقله — الصور والحواشي والتعليقات. لا يُحفظ شيء حتى تقول ذلك.","featuresPage.cards.markers.title":"علامات الأقسام، والبحث والاستبدال","featuresPage.cards.markers.body":"السطر الذي يبدأ بـ # علامة على شريط التنقل وفي قائمة انتقال. ويطابق البحث والاستبدال حالة الأحرف أو الكلمات الكاملة، ويُتراجع عنه بضغطة واحدة.","featuresPage.cards.timing.title":"الإيقاع والنقرة والمازورات","featuresPage.cards.timing.body":"انقر إيقاعك ليتلاءم BPM مع أدائك أنت، واسمع نقرة مع عدّ تمهيدي، وشاهد المازورة والضربة على الشاشة وكخطوط على شريط التنقل.","featuresPage.cards.rehearsal.title":"التدريب وتقرير التوقيت","featuresPage.cards.rehearsal.body":"اقرأ النص حتى نهايته وشاهد الزمن المخطط لكل قسم مقابل الزمن الفعلي، والوتيرة التي قرأت بها فعلًا. لا يسجّل إلا التوقيتات — لا ميكروفون، ولا صوت.","featuresPage.cards.skip.title":"تسميات لا تستغرق وقتًا","featuresPage.cards.skip.body":"حدّد «اللازمة» أو «[المقطع 1]» أو «## الجسر» ككلمات لا تؤديها: تبقى على الشاشة باهتة، ولا تستغرق شيئًا من زمن القراءة، فتبقى كلماتك على المازورة.","featuresPage.cards.control.title":"الاختصارات والدواسات والمفاتيح العامة","featuresPage.cards.control.body":"خريطة لكل الأوامر قابلة للبحث، مع الإشارة إلى التعارضات. تُعيَّن الدواسات وأجهزة التحكم عن بُعد كأي مفتاح، ويمكن لمفتاح أن يعمل بينما يكون تطبيق آخر في المقدمة.","featuresPage.cards.writing.title":"الإكمال التلقائي والإملاء والقراءة بصوت عالٍ","featuresPage.cards.writing.body":"اقتراحات للكلمات والعبارات بـ 18 لغة من قوائم داخل التطبيق، وإملاء بالإنجليزية يعمل على حاسوبك، وقراءة بصوت عالٍ بأصوات نظامك نفسه.","featuresPage.cards.look.title":"مظهرك، ولغتك","featuresPage.cards.look.body":"الخط والحجم والسماكة واللون والهوامش وتباعد الأسطر وخط القراءة، على كل الشاشات دفعة واحدة. يتحدث التطبيق 18 لغة، بسمة داكنة أو فاتحة.","featuresPage.cards.private.title":"بلا حساب، وبلا سحابة","featuresPage.cards.private.body":"النصوص ملفات عادية على حاسوبك، ولا يوجد قياس عن بُعد. والطلب الوحيد الذي يرسله التطبيق إلى الإنترنت هو التحقق من وجود إصدار أحدث، ولا يُثبَّت شيء دون موافقتك.","featuresPage.compare.title":"جنبًا إلى جنب مع تطبيقات التلقين التجارية","featuresPage.compare.intro":"يقف هنا Freally Teleprompt 1.5.0 — الإصدار المنشور، الذي يمكنك استخدامه اليوم — إلى جانب ستة تطبيقات تلقين تجارية. كل خانة تخص منتجًا آخر مأخوذة من صفحات الشركة المصنّعة نفسها أو من صفحته في متجر التطبيقات، وقد جرى التحقق منها في 2 أكتوبر 2026، والأسعار بالدولار الأمريكي كما كانت في أكتوبر 2026.","featuresPage.compare.feature":"الميزة","featuresPage.compare.row.price":"السعر (USD، أكتوبر 2026)","featuresPage.compare.freeToday":"مجاني اليوم","featuresPage.compare.unit.perMonth":"شهريًا","featuresPage.compare.unit.perYear":"سنويًا","featuresPage.compare.unit.once":"لمرة واحدة","featuresPage.compare.unit.onSale":"بسعر مخفَّض؛ عادةً $99","featuresPage.compare.row.systems":"تطبيق سطح مكتب لـ Windows وmacOS وLinux","featuresPage.compare.legend.yes":"متوفر","featuresPage.compare.legend.partly":"جزئيًا","featuresPage.compare.note.browser":"وفي متصفح الويب","featuresPage.compare.row.noAccount":"استخدامه دون إنشاء حساب","featuresPage.compare.legend.no":"غير متوفر","featuresPage.compare.legend.unknown":"لم يُتحقَّق منه","featuresPage.compare.row.offline":"يعمل دون اتصال بالإنترنت","featuresPage.compare.note.updateCheck":"التحقق من التحديثات وحده يتصل بالإنترنت","featuresPage.compare.note.afterRegistration":"بعد التسجيل عبر الإنترنت","featuresPage.compare.row.import":"يفتح ملفات Word وPDF","featuresPage.compare.note.ourFormats":"وأيضًا RTF والنص العادي وMarkdown","featuresPage.compare.note.wordIos":"Word على iPhone وiPad فقط","featuresPage.compare.note.textRtf":"النص العادي وRTF فقط","featuresPage.compare.row.bpm":"يضبط وتيرة التمرير على إيقاع موسيقي (BPM)","featuresPage.compare.row.pauses":"وقفات مؤقَّتة مكتوبة في النص","featuresPage.compare.row.mirror":"نص معكوس لزجاج التلقين","featuresPage.compare.row.devices":"يعرض النص على أجهزة أخرى","featuresPage.compare.note.ownNetwork":"على شبكتك أنت، في متصفح","featuresPage.compare.note.portal":"عبر بوابة الشركة المصنّعة، على الإنترنت","featuresPage.compare.note.internet":"عبر الإنترنت","featuresPage.compare.note.btWifi":"عبر Bluetooth أو Wi-Fi أو الإنترنت","featuresPage.compare.note.displayOrLan":"شاشة ثانية، أو جهاز آخر على الشبكة","featuresPage.compare.note.secondMonitor":"شاشة ثانية؛ والأجهزة اللوحية تحتاج إلى تطبيقات أخرى","featuresPage.compare.row.remotes":"دواسات القدم وأجهزة التحكم عن بُعد للعروض","featuresPage.compare.note.keyboardOnly":"اختصارات لوحة المفاتيح فقط","featuresPage.compare.row.voiceScroll":"التمرير يتبع صوتك","featuresPage.compare.note.removed":"أُزيل في 1.1.0","featuresPage.compare.note.paidAddon":"إضافة مدفوعة","featuresPage.compare.summaryTitle":"باختصار","featuresPage.compare.summary":"باختصار: من بين هذه السبعة، وحده Freally Teleprompt يذكر أنه يضبط وتيرة التمرير بـ BPM ويلتزم بالوقفات المؤقَّتة المكتوبة في النص، وهو الوحيد الذي يعمل على Windows وmacOS وLinux دون حساب ودون دفع.","featuresPage.compare.theyWinTitle":"أين يتفوّقون","featuresPage.compare.theyWin":"أين يتفوّقون: يمرّر PromptSmart وSpeakflow وTeleprompter.com النص بتتبّع صوتك، ويفعل TeleScroll ذلك بإضافة مدفوعة؛ أما Freally Teleprompt 1.5.0 فلا يفعل. ولدى PromptSmart وTeleprompter.com وTeleprompter Pro تطبيقات للهواتف والأجهزة اللوحية تسجّل الفيديو أثناء قراءتك وتحفظ نصوصك في سحابتها، ويضيف Speakflow أدوات كتابة بالذكاء الاصطناعي وتعاونًا في الوقت الفعلي.","featuresPage.compare.asOf":"عمود Freally Teleprompt هو الإصدار 1.5.0، وهو منشور، فيقارن الجدول ما يمكنك استخدامه اليوم. وسعره هو سعر اليوم: Freally Teleprompt مجاني اليوم، وقد تُباع الإصدارات المستقبلية. والمنتجات الأخرى تتغيّر أيضًا؛ وهذا الجدول محدَّث حتى 2 أكتوبر 2026.","featuresPage.why.title":"لماذا بُني بهذه الطريقة","featuresPage.why.engine.title":"محرّك واحد، يعدّ بالأحرف","featuresPage.why.engine.body":"السرعة أحرف في الثانية، فتتحرك المعاينة وجهاز العرض وكل هاتف عبر النص نفسه بالمعدّل نفسه أيًّا كان حجم الخط فيها. والمحرّك مكتوب مرتين، لنواة التطبيق ولواجهته، وتُبقى النسختان متطابقتين.","featuresPage.why.import.title":"محوِّل يقول ما الذي أسقطه","featuresPage.why.import.body":"يعدّ الاستيراد ما تعذّر عليه نقله بدلًا من أن يضيّعه في صمت، ولا يحوّل أبدًا شرطة مطبعية إلى وقفة لم يكتبها أحد.","featuresPage.why.isolate.title":"الملف التالف لا يستطيع إيقاف القراءة","featuresPage.why.isolate.body":"تُقرأ المستندات في عملية منفصلة بحدّ زمني، فملف PDF التالف يُنهي ذلك الاستيراد وحده، لا الملقّن.","featuresPage.why.local.title":"يبقى على جهازك","featuresPage.why.local.body":"بلا حساب، ولا قياس عن بُعد، ولا سحابة. نصوصك ملفات نصية عادية يمكنك فتحها في أي محرر، والمزامنة الشبكية تبقى على شبكتك أنت.","featuresPage.why.consent.title":"لا شيء يحدث من وراء ظهرك","featuresPage.why.consent.body":"لا تتغيّر الإعدادات إلا حين تضغط «تطبيق»، ولا يُحجَز مفتاح على مستوى النظام إلا حين تطلب ذلك، ولا يُثبَّت تحديث إلا بعد موافقتك.","featuresPage.why.keyboard.title":"في متناول لوحة المفاتيح","featuresPage.why.keyboard.body":"لكل عنصر تحكم حلقة تركيز، وتُبقي مربعات الحوار التركيز داخلها، وشريط التنقل منزلق حقيقي، ويُحترم تقليل الحركة وتقليل الشفافية.","featuresPage.coming.title":"ما الذي لم يأتِ بعد","featuresPage.coming.intro":"نقولها بوضوح، لأن قائمة الميزات التي تُخفي ثغراتها لا تستحق القراءة. كل ما في هذه الصفحة موجود في 1.5.0؛ والخطوات التي تليه على الطريق إلى 2.0، وكلٌّ منها موسومة بحالتها.","featuresPage.limits.title":"ما لا يفعله 1.5.0","featuresPage.limits.voice":"لا يمرّر النص بتتبّع صوتك: أنت تضبط الوتيرة، ويتولى مفتاح أو دواسة التحكم حين تتغيّر القراءة.","featuresPage.limits.dictation":"لا يفهم الإملاء إلا الإنجليزية؛ أما الإكمال التلقائي والواجهة فيغطيان اللغات الثماني عشرة كلها.","featuresPage.limits.phone":"لا يوجد تطبيق للهاتف أو الجهاز اللوحي: يمكن للهاتف أن يعرض النص عبر المزامنة الشبكية، للقراءة فقط، لكنه لا يستطيع التحكم فيه.","featuresPage.limits.recording":"لا يسجّل الفيديو أو الصوت أثناء قراءتك من الملقّن.","featuresPage.limits.wayland":"تحت Wayland على Linux، قد لا يعمل المفتاح المضبوط ليعمل بينما يكون تطبيق آخر في المقدمة، لأن Wayland لا يسمح للتطبيقات بحجز المفاتيح على مستوى النظام؛ أما المفاتيح داخل التطبيق فلا تتأثر.","featuresPage.coming.downloads":"لا توجد تنزيلات على هذا الموقع، ولا على هذه الصفحة.","docs.intro":"كيف تستخدم Freally Teleprompt، من أول تشغيل إلى القراءة على عُدّة التصوير.","docs.start.title":"البدء","docs.write.title":"اكتب نصًا","docs.import.title":"استيراد مستند","docs.find.title":"بحث واستبدال","docs.markers.title":"علامات الأقسام","docs.pauses.title":"شارات الوقفات","docs.pacing.title":"الوتيرة: الأحرف في الثانية أو BPM","docs.tempo.title":"الإيقاع والمازورات والنقرة","docs.rehearsal.title":"التدريب وتقرير التوقيت","docs.skip.title":"كلمات لا تؤديها","docs.playback.title":"التشغيل وأزراره","docs.shortcuts.title":"الاختصارات والدواسات والمفاتيح العامة","docs.countdown.title":"العدّ التنازلي للبدء","docs.projector.title":"جهاز العرض","docs.mirror.title":"المزامنة الشبكية","docs.readAloud.title":"القراءة بصوت عالٍ","docs.autocomplete.title":"الإكمال التلقائي","docs.dictation.title":"الإملاء","docs.settings.title":"المظهر واللغات والإعدادات","docs.access.title":"الجولة وإمكانية الوصول","docs.problems.title":"المشكلات والتحديثات","docs.privacy.title":"الخصوصية والشبكة","docs.start.p1":"تطبيق Freally Teleprompt ملقّن نصوص لـ Windows وmacOS وLinux، لمقدّمي العروض وصنّاع البث المباشر ومقدّمي البودكاست والممثلين والمغنّين ومؤدّي الراب. يُفتح في نافذة واحدة — نصوصك، والمحرر، والمعاينة، وأدوات التحكم في جهاز العرض — ولا يحتاج إلى حساب.","docs.start.p2":"في أول مرة يُفتح فيها، يعرض اتفاقية ترخيصه. مرّر إلى النهاية، ثم اختر «أوافق» أو «رفض وخروج». لا يمكن استخدام التطبيق حتى توافق؛ ويُحفظ جوابك، ولا تُسأل مرة أخرى إلا إذا تغيّرت الاتفاقية.","docs.start.p3":"ثم تعرض جولة مدتها دقيقة واحدة المحرر وأدوات ضبط الوتيرة وجهاز العرض. اكتب نصًا أو الصقه، واضبط وتيرتك، واضغط «تشغيل».","docs.start.p4":"لا توجد تنزيلات على هذا الموقع، والشيفرة المصدرية خاصة.","docs.write.p1":"النصوص ملفات ‎.ftscript: نص عادي في مجلد واحد، يمكن قراءته في أي محرر نصوص. افتح «النصوص» في شريط الأدوات لإنشائها وفتحها وإعادة تسميتها وحذفها. تعيدك قائمة الأحدث إلى ما كنت تعمل عليه، ويُحفظ كل شيء أثناء الكتابة، ويعيد التطبيق فتح آخر نص كان مفتوحًا لديك.","docs.write.p2":"اكتب في المحرر أو الصق من أي مكان. تحت تقدير زمن القراءة، يُظهر عدّاد مباشر للكلمات والأحرف ما ستؤديه فعلًا — فلا تُحتسب التسميات المتخطّاة وعلامات الوقفات — ويُنبّه تحذيرٌ إلى أي سطر طويل بما يكفي ليكون فقرة كاملة.","docs.import.p1":"اضغط «استيراد» في شريط الأدوات واختر مستند Word بامتداد ‎.docx، أو ملف RTF، أو PDF، أو ملف نص عادي، أو ملف Markdown. ترى النص الناتج، وتقريرًا، قبل حفظ أي شيء.","docs.import.p2":"تُحفظ الفقرات؛ ويُبسَّط الخط العريض والخطوط والألوان، لأن الملقّن يعرض خطًا واحدًا. وتصبح علامات الاقتباس المنحنية والشرطات الطويلة وعلامات الحذف علامات بسيطة، ويُقرأ الملف المحفوظ بترميز أقدم قراءة صحيحة، ويذكر التقرير ذلك.","docs.import.p3":"تُعدّ الصور والحواشي والتعليقات والرؤوس والتذييلات وعناوين الروابط والكائنات المضمَّنة وتُدرج في قائمة، ولا تُسقَط في صمت أبدًا. أما PDF فليست له بنية كهذه، لذا يذكر التقرير في حالة PDF أنه لم يستطع أن يعرف.","docs.import.p4":"سمِّ النص — يُقترح اسم مأخوذ من الملف — واضغط «استيراد». يُضاف إلى مكتبتك ويُفتح، ولا يكتب أبدًا فوق نص موجود بالفعل. تصل عناوين Markdown كأسطر تبدأ بـ #، فيأتي نص Markdown ومعه علامات أقسامه.","docs.import.p5":"تصبح الشرطة المطبعية واصلة عادية، ولا تتحول اثنتان منها إلى وقفة أبدًا، فلا تصل المسرحية المستوردة مليئة بوقفات لم يكتبها أحد. أما الملف النصي الذي كتبته بعلامات وقفات حقيقية فيحتفظ بها.","docs.find.p1":"اضغط Ctrl+F، أو «بحث» في شريط الأدوات، للبحث في النص المفتوح. يتحدّث عدد التطابقات وأنت تكتب؛ وينتقل Enter إلى التطابق التالي وShift+Enter إلى السابق، مع الالتفاف عند الطرفين.","docs.find.p2":"يضيّق «مطابقة حالة الأحرف» و«الكلمات الكاملة فقط» نطاق البحث، ويُبحث عمّا تكتبه حرفيًا. يغيّر «استبدال» التطابق الحالي ويغيّر «استبدال الكل» كل التطابقات؛ ويُتراجع عن أيٍّ منهما بضغطة Ctrl+Z واحدة.","docs.markers.p1":"ابدأ السطر بـ # — # المقطع 2، # سؤال وجواب، ## الجسر — فيصبح علامة قسم. وكل سطر يتكوّن من إحدى كلمات التخطّي لديك، مثل [اللازمة]، علامة أيضًا. لا شيء يحتاج إلى إعداد.","docs.markers.p2":"تظهر العلامات في قائمة انتقال بجانب شريط التنقل تُظهر القسم الذي أنت فيه، وتُرسم خطوطًا على شريط التنقل نفسه. يمرّ عليها «القسم التالي» و«القسم السابق»؛ وينتقل «القسم السابق» أولًا إلى بداية القسم الذي أنت فيه، كزر المقطوعة السابقة. واختيار إحداها يحرّك كل الشاشات، بما فيها جهاز العرض.","docs.pauses.p1":"اكتب -- (مسافة، ثم شرطتان، ثم مسافة) لوقفة قصيرة، أو ‎--N لتوقّف مدته N ثانية. تصبح كلٌّ منها شارة في المحرر: لا يقف المؤشر إلا قبلها أو بعدها، وضغطة Backspace واحدة تحذفها، وShift مع مفتاح سهم يحددها كاملة. اضبط طول -- العادية من الإعدادات ← القراءة.","docs.pauses.p2":"ينقل النسخ واللصق الشارات سليمة، ويُرتَّب التباعد في النص الملصوق لتحطّ كل وقفة كشارة نظيفة. وأثناء تشغيل النص، تُضاء كل وقفة حين تصل إليها القراءة ويتوقف التمرير طوال مدتها — على المعاينة وجهاز العرض والمزامنة الشبكية على حد سواء.","docs.pacing.p1":"اضبط السرعة بالأحرف في الثانية: معدّل قراءة حقيقي تتبعه كل الشاشات، أيًّا كان حجم الخط فيها. أو انتقل إلى BPM، من 20 إلى 250، لتقرأ كلمات الأغاني والمقاطع في تزامن مع مقطوعة.","docs.pacing.p2":"كلاهما يدير المحرّك نفسه، وتغيير أيٍّ منهما أثناء تشغيل النص يعيد ضبط وتيرته فورًا.","docs.tempo.p1":"يتحوّل الإيقاع إلى سرعة قراءة عبر رقم واحد: كم حرفًا تقرأ في الضربة. من الإعدادات ← التوقيت ← إيقاعك أنت، اضغط «انقر» ثلاث مرات أو أكثر على الإيقاع الذي تؤدي به، ثم اختر «استخدم هذا الإيقاع»؛ و«العودة إلى الافتراضي» يلغي ذلك. بعدها لا يعرض مربع BPM إلا الإيقاعات التي يستطيع المحرّك بلوغها.","docs.tempo.p2":"حين يكون BPM مفعّلًا، أو تكون النقرة مفعّلة، تظهر المازورة والضربة فوق شريط التنقل وتُرسم عليه خطوط المازورات. اضبط «الضربات في المازورة»، من 2 إلى 12، من الإعدادات ← التوقيت.","docs.tempo.p3":"فعِّل «تشغيل نقرة على الإيقاع الحالي» لتسمع نقرة خافتة على كل ضربة، أعلى نبرةً على الضربة الأولى من كل مازورة؛ ويصبح العدّ التنازلي للبدء عدّها التمهيدي. يولّد التطبيق الصوت بنفسه ويوقّت كل نقرة على ساعة الصوت، فلا تنحرف. وتصمت ما دامت القراءة بصوت عالٍ تتكلم.","docs.rehearsal.p1":"فعِّل «تدرَّب وقِس زمن قراءتي» تحت أزرار التشغيل، واضغط «تشغيل» واقرأ بصوت عالٍ كما ستفعل في اليوم الموعود. أوقِف مؤقتًا، أو ارجع، أو غيّر السرعة: كل ذلك جزء من القياس.","docs.rehearsal.p2":"ألغِ تفعيله فيُفتح تقرير التدريب: صف لكل قسم، فيه الزمن الذي كان ينبغي أن يستغرقه بوتيرتك، والزمن الذي استغرقه، والفرق. والأقسام هي فقراتك، أو علامات أقسامك حين يكون النص مقسّمًا بها. وإن قرأت بوتيرة مختلفة، يعرض عليك التقرير تلك السرعة، وتطبّقها نقرة واحدة.","docs.rehearsal.p3":"أثناء التدريب، يظهر تحذير هادئ ما إن تتأخر القراءة عن خطتها أو تتقدم عليها بثلاث ثوانٍ أو أكثر. يسجّل التدريب التوقيتات ولا شيء غيرها: لا يفتح أي ميكروفون ولا يحتفظ بأي صوت، ولا يمكن تشغيله مع القراءة بصوت عالٍ في الوقت نفسه.","docs.skip.p1":"تسميات الأقسام — اللازمة، المقطع 2، الجسر — معالم تراها قادمة لكنك لا تنطقها أبدًا. اذكرها في الإعدادات ← التوقيت ← كلمات لا تؤديها، واحدة في كل سطر. تبدأ القائمة فارغة، لأنها تغيّر طريقة توقيت النص.","docs.skip.p2":"السطر الذي لا يحوي سوى تسمية يُتخطّى بأكمله: تُتجاهل الأقواس وعلامات # والنقطتان والرقم في آخره، فتتطابق «اللازمة» و«[المقطع 1]» و«## الجسر» و«اللازمة:» جميعًا. والكلمة نفسها داخل سطر حقيقي لا تتخطى إلا نفسها. تتجاهل المطابقة الفرق بين الأحرف الكبيرة والصغيرة، ولا تطابق إلا الكلمات الكاملة.","docs.skip.p3":"يبقى النص المتخطّى على الشاشة باهتًا، فيظل المقدّم يراه قادمًا، ولا تنطقه القراءة بصوت عالٍ أبدًا. ولأن التسمية لا تستغرق وقتًا، يتجاوزها التمرير فورًا — وتبقى كلماتك على المازورة التي كتبتها لها.","docs.playback.p1":"التشغيل والإيقاف المؤقت والإيقاف و«خطوة للخلف» و«خطوة للأمام» أزرار على الشاشة؛ اضغط باستمرار على «خطوة للخلف» أو «خطوة للأمام» لمواصلة الحركة. أدِر عجلة الفأرة للتنقل، أو انقر كلمة لتبدأ منها، أو مرّر المؤشر فوق شريط التنقل لترى الكلمات عند تلك النقطة.","docs.playback.p2":"يُظهر شريط التنقل زمن القراءة المنقضي والإجمالي، بما فيه الوقفات. ويُبقي دليل القراءة الكلمة الحالية على سطر القراءة، ولا تخرج آخر كلمة مضاءة عن مجال الرؤية أبدًا.","docs.shortcuts.p1":"افتح «الاختصارات» في شريط الأدوات. اضغط التعيين الذي تريد تغييره، ثم اضغط المفتاح أو جهاز التحكم أو الدواسة التي تريدها؛ ويتركه Esc كما كان. ابحث باسم الأمر أو بالمفتاح نفسه. وإن تشارك أمران مفتاحًا واحدًا، يذكر الصفّان ذلك؛ امسح أحدهما بـ ×، أو اختر «استعادة الإعدادات الافتراضية».","docs.shortcuts.p2":"ترسل معظم دواسات القدم وأجهزة التحكم عن بُعد للعروض التقديمية مفاتيح عادية، غالبًا من F13 إلى F24، فتُعيَّن دون برنامج تشغيل ودون إعداد. وتتبع التعيينات المفتاح الفعلي، لا الحرف المطبوع عليه، فتصمد أمام تغيير تخطيط لوحة المفاتيح.","docs.shortcuts.p3":"يطلب عمود «في أي مكان» من نظامك أن يوصل المفتاح حتى حين يكون تطبيق آخر في المقدمة — تطبيق كاميرا، أو DAW، أو OBS. لا يُحجَز شيء حتى تضبطه، والمفتاح الذي يملكه برنامج آخر بالفعل يذكر ذلك. وتحت Wayland على Linux، لا تستطيع التطبيقات حجز المفاتيح على مستوى النظام، ويخبرك مربع الحوار بذلك.","docs.shortcuts.p4":"أثناء الكتابة، تعمل مفاتيح المسافة والأسهم وHome كالمعتاد: فالمفتاح وحده، من دون مفاتيح تعديل، لا يشغّل أمره إلا خارج المحرر.","docs.countdown.p1":"اضبط «العد التنازلي قبل البدء» من الإعدادات ← القراءة، فيعدّ الضغط على «تشغيل» تنازليًا ذلك العدد من الثواني أولًا، على المعاينة وجهاز العرض، فيحظى المقدّم بلحظة قبل أن تتحرك الكلمة الأولى. وحين تكون النقرة مفعّلة، يكون العدّ التنازلي هو العدّ التمهيدي أيضًا.","docs.projector.p1":"اضغط «فتح جهاز العرض» واختر الشاشة التي يقرأ منها المقدّم: يملأ النص تلك الشاشة من الحافة إلى الحافة. فعِّل العكس لزجاج مقسّم الأشعة، الذي لولا ذلك لظهر الانعكاس فيه مقلوبًا. ولجهاز العرض أزرار تشغيله وشريط تنقله ومفاتيحه الخاصة لمن يقرأ.","docs.projector.p2":"تخطّط المعاينة وجهاز العرض النص بالعرض نفسه ثم تغيّران مقياسه ليلائم الشاشة، فتكسران الأسطر في المواضع نفسها. تحقّق من أن النص المعكوس يُقرأ بشكل صحيح عبر زجاجك أنت قبل التصوير.","docs.mirror.p1":"لعرض النص على هاتف أو جهاز لوحي أو حاسوب محمول ثانٍ، افتح الإعدادات ← الشبكة ← المزامنة عبر شبكتي وفعِّل «مزامنة النص مع الأجهزة على شبكتي». وفعِّل أيضًا «السماح لأجهزة أخرى، وليس هذا الحاسوب فقط» — فمن دونه لا تستجيب المزامنة إلا على هذا الحاسوب — ثم اضغط «تطبيق». يظهر رابط ورمز QR: امسح الرمز، أو افتح الرابط في متصفح على الشبكة نفسها.","docs.mirror.p2":"تتبع المزامنة المحرّك نفسه، فيكون كل جهاز على الكلمة نفسها التي عند المشغّل. ويضبط كل جهاز حجم نصه الخاص بـ A−‎ وA+‎ دون أن يغيّر شاشة أي شخص آخر.","docs.mirror.p3":"يقدّم التطبيق نفسه الصفحة مباشرة إلى أجهزتك — لا عبر هذا الموقع أبدًا، إذ لن يسمح المتصفح له بالوصول إلى جهاز على شبكتك على أي حال. وهي للقراءة فقط: لا يستطيع أي متصفح أن يبدأ أو يوقف أو ينتقل أو يعدّل أي شيء. ويحمل رابطها مفتاحًا يتغيّر في كل مرة يبدأ فيها التطبيق. وهي تعمل بـ HTTP عادي، فلا يكون المفتاح مشفَّرًا في الطريق: استخدمها على شبكة تثق بها، لا على شبكة Wi-Fi عامة.","docs.mirror.p4":"إن لم يستطع جهاز الاتصال: تحقّق من الخيارين كليهما؛ وتأكد من أنه على الشبكة نفسها، لا على بيانات الهاتف المحمول أو على شبكة ضيوف تعزل الأجهزة بعضها عن بعض؛ واسمح للتطبيق بالمرور عبر جدار الحماية للشبكات الخاصة حين يطلب نظامك ذلك؛ وإن ذكرت الإعدادات أن المزامنة تعذّر بدؤها، فغيّر المنفذ واضغط «تطبيق» مرة أخرى.","docs.readAloud.p1":"فعِّل «القراءة بصوت عالٍ باستخدام تركيب الكلام الخاص بنظام التشغيل» لتسمع النص بأصوات نظامك نفسه: Windows OneCore أو SAPI، أو macOS AVSpeechSynthesis، أو Speech Dispatcher أو espeak-ng على Linux. ولا يُرفق أي صوت مع التطبيق.","docs.readAloud.p2":"تتحكم أزرار التشغيل وشريط التنقل والنقر على كلمة في الكلام، ويتبعه التظليل — كلمةً كلمة حيث يُبلغ النظام عن حدود الكلمات، وبوتيرتك في غير ذلك. تصبح الوقفات لحظات صمت قصيرة، ولا يُقرأ -- أبدًا على أنه «شرطة».","docs.readAloud.p3":"القراءة بصوت عالٍ للمعاينة فقط: لا تحرّك جهاز العرض أبدًا. ويبقى مربع الاختيار مقفلًا ما دامت القراءة قيد التشغيل أو موقوفة مؤقتًا، حتى تضغط «إيقاف». تحقّق من أنها تتكلم على الحاسوب الذي ستقدّم منه، خاصة على Linux.","docs.autocomplete.p1":"أثناء الكتابة، تظهر بقية الكلمة باهتة أمام المؤشر؛ وأنهِ كلمة واضغط مفتاح المسافة، فقد يقترح عليك عبارة شائعة كاملة. يقبلها Tab، ويرفضها Esc، ومواصلة الكتابة تتجاهلها.","docs.autocomplete.p2":"لكل لغة من اللغات الثماني عشرة قوائم كلمات وعبارات خاصة بها — 463,985 كلمة و344,891 عبارة إجمالًا — داخل التطبيق، ولا تُحمَّل إلا اللغة التي تكتب بها. من الإعدادات ← المحرر، فعّله أو عطّله واختر لغته، التي يمكن أن تختلف عن لغة التطبيق.","docs.autocomplete.p3":"بُنيت القوائم من مجموعة جمل Tatoeba (CC BY 2.0 FR)‎، المذكور مصدرها في ملف NOTICE الذي يأتي مع التطبيق. إنه بحث في قاموس — فوري ومتوقَّع ويعمل دون اتصال، بلا نموذج.","docs.dictation.p1":"افتح الإعدادات ← الصوت، وفعِّل «اكتب النص بصوتي» واضغط «تطبيق». يظهر زر تسجيل دائري فوق النص: اضغطه وتكلّم، فيُكتب ما تقوله حيث يكون مؤشرك. اضغطه مرة أخرى للإيقاف؛ فالميكروفون لا يكون مفتوحًا إلا بين الضغطتين.","docs.dictation.p2":"النص المُملى نص عادي كبقية النص، وCtrl+Z يستعيد شيئًا واحدًا قلته، لا الجلسة كلها. توقّع أن تحتاج إلى ترتيب علامات الترقيم والأسماء: إنه طريق سريع إلى مسودّة، لا إلى نص مكتمل.","docs.dictation.p3":"لا يفهم الإملاء إلا الإنجليزية. يستخدم Vosk، وهو محرّك مفتوح المصدر للتعرّف على الكلام، مع نموذج كلام إنجليزي صغير — شبكة عصبية مدرَّبة حجمها نحو 40 ميغابايت — يأتي داخل التطبيق. يعمل على حاسوبك، ودون اتصال، ولا يرفع شيئًا ولا يُنزّل شيئًا، ولا يحفظ سوى النص الذي تراه. وهو معطّل حتى تفعّله. وإن كان النص متزامنًا مع شبكتك، فإن الكلمات المُملاة تصل إلى تلك الأجهزة فور كتابتها، كالكتابة تمامًا.","docs.settings.p1":"من الإعدادات ← المظهر، اضبط الخط وسماكته ولون النص، والهوامش الجانبية، وتباعد الأسطر، وموضع خط القراءة؛ أما حجم الخط فتحت «القراءة». وتسري كلها على المعاينة وجهاز العرض والمزامنة الشبكية معًا.","docs.settings.p2":"تعمل الإعدادات على مسودّة: لا يتغيّر شيء حتى تضغط «تطبيق»، و«إلغاء» يعيد ما كان لديك. اختر إحدى 18 لغة، أو «مثل نظامي». والسمة «داكن» أو «فاتح» أو «مثل نظامي»؛ ويبقى سطح القراءة عالي التباين أيًّا كان اختيارك.","docs.settings.p3":"حين يكون «التصغير إلى شريط النظام» مفعّلًا، من الإعدادات ← عام، يضع التصغير التطبيق في شريط النظام بدلًا من شريط المهام. و«أعد عرض الجولة»، وهو أيضًا تحت «عام»، يعيد تشغيل الجولة الترحيبية.","docs.access.p1":"في أول مرة يُفتح فيها التطبيق، بعد الترخيص، تعرض جولة من أربع خطوات المحرر وعلامات الوقفات فيه، وأدوات ضبط الوتيرة، وجهاز العرض. يغلقها «تخطٍّ» أو Esc أو النقر خارجها نهائيًا؛ وتعيدها الإعدادات ← عام ← أعد عرض الجولة.","docs.access.p2":"يُظهر كل عنصر تحكم حلقة تركيز حين تصل إليه من لوحة المفاتيح. يبقى Tab داخل مربع الحوار المفتوح، ويغلقه Esc، ويعود التركيز إلى الزر الذي فتحه. وشريط التنقل منزلق حقيقي: تحرّك مفاتيح الأسهم حرفًا واحدًا، وPage Up وPage Down شاشة كاملة، وينتقل Home وEnd إلى أيٍّ من الطرفين.","docs.access.p3":"إن طلب نظامك تقليل الحركة، تُلغى الرسوم المتحركة والتمويه بينما يظل النص نفسه يتمرر؛ ومع تقليل الشفافية، تُعتّم مربعات الحوار الخلفية بدلًا من تمويهها.","docs.problems.p1":"حين يحدث خطأ يستطيع التطبيق إخبارك به، يظهر بجانب رسالته زر «إبلاغ». وبعد التعطّل، يعرض التشغيل التالي شريطًا فيه «إبلاغ» و«تجاهل».","docs.problems.p2":"يفتح «إبلاغ» صفحة الإبلاغ الخاصة بـ Freally Teleprompt في متصفحك، والتفاصيل التقنية معبّأة مسبقًا: يمكنك قراءتها، لا تغييرها. أضف ما كنت تفعله، وعنوان بريد إلكتروني إن شئت. لا يُرسَل شيء ما لم تضغط «إرسال» في تلك الصفحة، ولا يُرسَل شيء في الخلفية أبدًا.","docs.problems.p3":"مرة واحدة في كل تشغيل، يسأل التطبيق GitHub هل يوجد إصدار أحدث. فإن وُجد، ترى رقم إصداره وملاحظات الإصدار وتختار نعم أو لا؛ ويُتحقَّق من التحديث مقابل مفتاح توقيع داخل التطبيق قبل تثبيته. وحين تكون غير متصل أو على أحدث إصدار بالفعل، لا يقول شيئًا. ويعيد «التحقق من التحديثات» في شريط الأدوات السؤال في أي وقت.","docs.privacy.p1":"بلا حساب ولا قياس عن بُعد. نصوصك ملفات ‎.ftscript على حاسوبك، حيث تحفظها، ولا يتلقاها مؤلف التطبيق أبدًا.","docs.privacy.p2":"الطلب الوحيد الذي يرسله التطبيق إلى الإنترنت هو التحقق من التحديثات، ولا يرسل أي نص ولا أي إعدادات ولا أي معرّف. ولا يغادر تقرير المشكلة إلا من صفحة الإبلاغ في متصفحك، حين تضغط «إرسال». ويبقى جهاز العرض والمزامنة الشبكية على شاشاتك أنت وشبكتك أنت.","docs.privacy.p3":"يُستخدم تعلّم الآلة في موضع واحد: نموذج الكلام الخاص بالإملاء، الذي يعمل على حاسوبك ويبقى معطّلًا حتى تفعّله. أما الإكمال التلقائي فبحث في قاموس، والقراءة بصوت عالٍ تستخدم أصوات نظامك نفسه، ولا يُرسَل شيء مما تكتبه أو تقوله إلى أي خدمة ذكاء اصطناعي.","kit.skip":"الانتقال إلى المحتوى","kit.nav.site":"الموقع","kit.nav.home":"الرئيسية","kit.nav.features":"الميزات","kit.nav.documentation":"التوثيق","kit.nav.changelog":"سجل التغييرات","kit.nav.language":"اللغة","kit.nav.allApps":"كل تطبيقات Freally","kit.cta.features":"شاهد كل الميزات","kit.cta.docs":"اقرأ التوثيق","kit.price":"Freally Teleprompt مجاني اليوم، لكنه قد لا يبقى مجانيًا إلى الأبد: قد تُباع الإصدارات المستقبلية.","kit.noDownloads":"لا توجد تنزيلات بعد، والشفرة المصدرية خاصة.","kit.label.overview":"نظرة عامة","kit.label.inside":"في الداخل","kit.label.roadmap":"خارطة الطريق","kit.ladder.done":"منجز","kit.ladder.planned":"مخطط له","kit.ladder.goal":"الهدف","kit.label.honesty":"الصراحة","kit.family.label":"عائلة Freally","kit.family.title":"<span class=\"hl-muted\">عائلة واحدة.</span> <span class=\"hl-bright\">ثمانية تطبيقات.</span>","kit.cta.label":"ما الذي تغيّر","kit.cta.title":"<span class=\"hl-muted\">كل إصدار،</span> <span class=\"hl-bright\">مدوَّن.</span>","kit.cta.lede":"يسرد سجل التغييرات كل ما تغيّر في Freally Teleprompt، إصدارًا بعد إصدار، بثماني عشرة لغة.","kit.cta.changelog":"اقرأ سجل التغييرات","kit.footer.thisApp":"هذا التطبيق","kit.footer.family":"عائلة Freally","kit.status.devVersion":"قيد التطوير · v1.5.0","kit.head.features":"<span class=\"hl-muted\">كل ما يفعله،</span> <span class=\"hl-bright\">جنبًا إلى جنب.</span>","kit.label.numbers":"بالأرقام","kit.label.free":"مجاني اليوم","kit.label.compare":"مقارنة","kit.label.principles":"المبادئ","kit.label.limits":"الحدود","kit.states.title":"ماذا تعني الحالات","kit.states.done":"مبنيّ وموسوم، لكنه ليس تنزيلًا على هذا الموقع","kit.states.planned":"لم يُبنَ بعد","kit.states.goal":"الإصدار الذي يقود إليه الطريق","kit.states.ladder":"شاهد كل درجة على الطريق","kit.head.documentation":"<span class=\"hl-muted\">كيف يعمل،</span> <span class=\"hl-bright\">خطوة بخطوة.</span>","kit.search.placeholder":"ابحث في التوثيق","kit.docs.contents":"المحتويات","kit.head.changelog":"<span class=\"hl-muted\">كل تغيير،</span> <span class=\"hl-bright\">إصدارًا بعد إصدار.</span>","kit.changelog.lede":"الأحدث أولًا: كل ما تغيّر في Freally Teleprompt، بكل لغة يتحدث بها هذا الموقع.","kit.changelog.versions":"الإصدارات","kit.changelog.unreleased":"غير منشور","kit.search.none":"لا شيء في هذا الموقع يطابق ذلك.","kit.zoom.close":"إغلاق","changelog.69c6a54708de":"<span class=\"release__meta\"><span class=\"release__ver\">لم يُصدَر بعد</span></span>","changelog.c205924de0fe":"التوثيق","changelog.3ba1bf71dedb":"<strong>أُعيد بناء الموقع</strong> بتصميم عائلة Freally، وهو يتحدث لغات التطبيق الثماني عشرة كلها — بما فيها سجل التغييرات هذا. ولا يقدّم أي تنزيلات.","changelog.184abbf86c34":"<span class=\"release__meta\"><span class=\"release__ver\">v1.5.0</span></span><span class=\"release__title\">5 أغسطس 2026</span>","changelog.4a6a7a1ffbc7":"أي شيء في الغرفة يمكنه أن يتحكم في الملقّن.","changelog.6b02e0d363a4":"الإضافات","changelog.21717d79a98c":"<strong>دواسات القدم وأجهزة التحكم عن بُعد للعروض التقديمية.</strong> الدواسة هي الطريقة التي يُدار بها الملقّن فعلًا أثناء التصوير — فيداك على الكاميرا، لا على لوحة المفاتيح. افتح <strong>الاختصارات</strong>، واضغط التعيين الذي تريد تغييره، ثم اضغط الدواسة: ما ترسله هو ما يُحفَظ، بلا برنامج تشغيل ولا إعداد. ترسل معظم الدواسات وأجهزة التحكم المفاتيح <code>F13</code>–<code>F24</code> تحديدًا لأن لا شيء آخر يستخدمها، وصارت هذه المفاتيح تُعيَّن الآن كأي مفتاح آخر.","changelog.87aef9902031":"<strong>مفاتيح تعمل حين لا يكون Freally Teleprompt في المقدمة.</strong> عادةً ما يكون المشغّل في تطبيق كاميرا أو في DAW أو OBS، لذا يمكن منح كل أمر من أوامر التحكم بالتشغيل تعيينًا ثانيًا يوصله نظام التشغيل إليك أينما كنت.","changelog.d6a3a80ffa2c":"<strong>لا يُحجَز شيء حتى تطلب ذلك.</strong> لا يُسجَّل أي مفتاح على مستوى النظام افتراضيًا — فانتزاع مفتاح من كل البرامج الأخرى دون استئذان ليس شيئًا ينبغي لتطبيق أن يفعله في أول تشغيل له.","changelog.e134c7c903f4":"<strong>المفتاح المرفوض يقول ذلك.</strong> إذا كان برنامج آخر يملك التركيبة بالفعل، يخبرك الصف بذلك مع السبب. وتحت Wayland، الذي لا يسمح للتطبيقات بحجز المفاتيح على مستوى النظام إطلاقًا، يقول مربع الحوار ذلك أيضًا بدلًا من عرض تعيين لا يفعل شيئًا في صمت.","changelog.dfedb41c2cf4":"<strong>خريطة لكل الأوامر قابلة للبحث وإعادة التعيين</strong>، مع كشف التعارضات — ابحث باسم الأمر، أو بالمفتاح نفسه حين تريد أن تعرف ما الذي يفعله <code>F13</code> حاليًا. امسح أي تعيين، أو استعد الإعدادات الافتراضية التي يأتي بها التطبيق، في أي وقت.","changelog.b74f3602a847":"<strong>جدول واحد يدير كل ذلك.</strong> المعاينة ونافذة جهاز العرض والدواسة والاختصار على مستوى النظام كلها تقرأ التعيينات نفسها، فتغيير مفتاح يغيّره في كل مكان دفعة واحدة — بما في ذلك جهاز عرض المقدّم، الذي يتبع إعادة التعيين دون أن يُعاد فتحه.","changelog.3573af4808a8":"لا تزال مفاتيح المسافة والأسهم وHome تعمل كالمعتاد أثناء كتابتك للنص: فالمفتاح وحده، من دون مفاتيح تعديل، لا يشغّل أمره إلا حين لا تكون في المحرر.","changelog.1246fc93bca0":"الإصلاحات","changelog.07ff9553768e":"<strong>استيراد المستندات (<code>Import</code> في 1.4.0)، والفكرة الجامعة هنا: المحوِّل الذي يغيّر نصك في صمت أسوأ من محوِّل يرفضه.</strong>","changelog.0ec8d88f6052":"<strong>لم يعد ملف PDF يدّعي معرفة ما تركه.</strong> تُقرأ كل الصيغ الأخرى بالمرور على نموذج المستند، لذا فإن «لم يُترك شيء آخر» أمر يستطيع المستورِد التحقق منه فعلًا. أما PDF فليست له بنية كهذه — والقائمة الفارغة هناك تعني <em>لم نستطع أن نعرف</em> — وقول غير ذلك كان طمأنة زائفة في الصيغة الأرجح أن تحمل أشكالًا وحواشي.","changelog.7ea47b0b9557":"<strong>لم يعد مربع النص في Word يُبلَّغ عنه كصورة مفقودة.</strong> كان نصه يُستورد طوال الوقت، ويُحتسب في الوقت نفسه صورةً أُسقطت. وصار الآن فقرة مستقلة بدلًا من أن يُقحَم في أي سطر صادف أن يكون مرساه — فعبارة «ننتقل أمام الكاميرا إلى اللقطة الواسعة» ليست ما يقوله المستند.","changelog.9962e4f893ac":"<strong>تُحتسب الصور والترويسات المتكررة مرة واحدة، وفي مواضع استخدامها فقط.</strong> كانت الصورة الواحدة تُعدّ صورتين، ويكتب Word ثلاثة رؤوس وثلاثة تذييلات في كل مستند سواء استُخدمت أم لا — فكانت الترويسة المتكررة الواحدة تُعدّ ستًّا. والمشغّل الذي يقرأ «الصور المتروكة: 2» يذهب باحثًا عن صورة ثانية لم توجد قط.","changelog.07aaaf2b256f":"<strong>لم تعد المحارف التي يخزّنها Word كعناصر تضيع في صمت</strong> — فقد كان <code>co‑operate</code> يُستورد على أنه <code>cooperate</code>. ورسم الخط الرمزي يُحتسب الآن شيئًا متروكًا بدلًا من تخمينه، لأن نقطة ترميزه فهرس داخل خط، لا محرف.","changelog.c15eb04425e7":"<strong>صار الملف الذي يدّعي أنه يونيكود وليس كذلك يُبلَّغ عنه.</strong> بعض الأدوات تختم البايتات الثلاثة لعلامة UTF-8 ثم تكتب نصًا أوروبيًا غربيًا رغم ذلك؛ وكان هذا الملف يُستورد وقد استُبدل كل حرف يحمل علامة تشكيل بـ <code>�</code> <strong>و</strong>التقرير يقول إن شيئًا لم يُسقَط — وهو الإخفاق نفسه الذي وُجدت ملاحظة الترميز لمنعه، وقد وقع عبر المسار الوحيد الذي تخطّى الفحص.","changelog.3e2d09e4e749":"<strong>توحيد الشَّرطات لا يزال عاجزًا عن اختلاق وقفة.</strong> كانت مسافة صفرية العرض أو بايت علامة شارد بين شرطتين — وهو ما تحمله عادةً النصوص المنقولة من الويب ومن PDF — تقسم السلسلة إلى اثنتين، فيُستورد <code>a —​— b</code> كوقفة <code> -- </code> لم يكتبها أحد. وسلك RTF المنعطف الخاطئ نفسه عبر طريق مختلف.","changelog.cdc8dc821ad8":"<strong>RTF: لم تعد الصورة أو الكائن المضمَّن يتسرّب إلى النص.</strong> كانت الحمولة الثنائية تُقرأ كأنها نص، فكان أول بايت <code>}</code> داخلها — والبيانات الثنائية العشوائية تحتويه مرة كل 256 بايتًا تقريبًا — يُنهي التخطّي مبكرًا ويُخرج الباقي إلى النص.","changelog.c62855d7561c":"<strong>RTF: تنجو الرموز التعبيرية وسائر المحارف الواقعة خارج المستوى الأساسي.</strong> فهي تصل كنصفين لزوج بديل، وليس أيٌّ من النصفين محرفًا بذاته، فكان الاثنان يُسقَطان. وصارت المسافات والواصلات غير القابلة للكسر تُستورد كما هي أيضًا.","changelog.456985ca40d6":"<strong>لم يعد التطبيق يتجمّد أثناء قراءة مستند.</strong> كان ملف PDF كبير قادرًا على تجميد النافذة مدة تصل إلى تسعين ثانية.","changelog.5ff5476a8e49":"<strong>لم يعد الاستيراد البطيء يحطّ في مربع الحوار الخطأ.</strong> كنت تغلقه، ثم تعيد فتحه، وتختار ملفًا مختلفًا، فتصل نتيجة المستند الأول وتستبدل التقرير والمعاينة <em>والاسم</em> — فيحفظ الضغط على «استيراد» نصًا لم تختره، باسم تغيّر من تحت يدك.","changelog.ca076d4847ef":"<strong>لم يعد الحفظ الفاشل يترك وراءه بقايا.</strong> إذا فشلت الكتابة — مجلد للقراءة فقط، أو قرص ممتلئ، أو ملف أقفله برنامج مزامنة — كان نص فارغ يبقى في المكتبة بالاسم الذي اخترته، ثم يفشل الاستيراد مجددًا برسالة «يوجد نص بهذا الاسم بالفعل». وكان عليك حذفه يدويًا. والتراجع لا يُخفي الخطأ الحقيقي أبدًا.","changelog.81f5afe81f74":"<strong>البحث والاستبدال (<code>Find</code> في 1.4.0)</strong>","changelog.df4d2a98d916":"<strong>صار «استبدال» يعدّل النص كما هو الآن، لا كما كان قبل لحظة.</strong> كان كلٌّ من «استبدال» و«استبدال الكل» يُحسب على نسخة تتأخر عن المحرر بمقدار رحلة ذهاب وإياب — فكانت العبارة المُملاة التي تصل في تلك الفترة تُكتب فوقها وتضيع، وكان موضع التطابق قد يشير إلى المحارف الخطأ.","changelog.0cc222aab642":"<strong>صار الاستبدال بنص يحتوي ما بحثت عنه يتقدّم إلى الأمام.</strong> كان استبدال «من» بـ«منزل» يحوّل كلمة واحدة إلى «منزلزل» عبر ثلاث ضغطات بينما بقيت الكلمتان الأخريان على حالهما، وكان العدّاد يقرأ «1 من 3» طوال الوقت.","changelog.fa5b9ccac936":"<strong>تقرير التدريب (وضع التدريب في 1.3.0)</strong>","changelog.e72cfed29d53":"<strong>لم يعد عنوان شارد واحد يُفسد التقرير.</strong> كان نص من اثنتي عشرة فقرة يحمل <code># Title</code> واحدًا من استيراد Markdown — أو سطرًا واحدًا من قائمة اللقطات نصه <code>#3 CAMERA B</code> — ينكمش من اثني عشر صفًا إلى صفين، فتضيع توقيتات الفقرات التي وُجد التقرير من أجلها. العلامة الواحدة تُعنون النص؛ ولا تقسّمه إلى أقسام.","changelog.cc295a583a87":"<span class=\"release__meta\"><span class=\"release__ver\">v1.4.0</span></span><span class=\"release__title\">4 أغسطس 2026</span>","changelog.4f39388d525b":"إدخال النص، والتنقّل في أرجائه.","changelog.2bfa1e157a29":"<strong>افتح الملف الذي أُرسل إليك.</strong> حتى الآن كانت الطريقتان الوحيدتان لوصول النص إلى الملقّن هما الكتابة واللصق، وليس هكذا يصل أي نص. يقرأ زر <strong>استيراد</strong> في شريط الأدوات <strong>Word (<code>.docx</code>) وRTF وPDF والنص العادي وMarkdown</strong> ويحوّلها إلى نص ملقّن نظيف: تُحفظ الفقرات، ويُبسَّط الخط العريض والخطوط والألوان، وتُوحَّد علامات الاقتباس المنحنية والشرطات الطويلة وعلامات الحذف، ويُقرأ الملف المحفوظ بترميز خاطئ ويُبلَّغ عنه بدلًا من عرضه رموزًا مشوّهة.","changelog.514edf636361":"<strong>يخبرك بما لم يستطع نقله</strong> — الصور والحواشي والتعليقات والرؤوس والتذييلات وعناوين الروابط والكائنات المضمَّنة، ولكلٍّ منها عدده. فالمحوِّل الذي يُسقطها في صمت ستكتشف أمره أثناء التصوير.","changelog.b9c0ccd7f34c":"<strong>لا يُحفظ شيء حتى تقول ذلك.</strong> ترى النص والتقرير، وتسمّي النص، وعندها فقط يظهر ملف في مكتبتك — ولن يكتب الاستيراد أبدًا فوق نص موجود بالفعل.","changelog.d2b1a7638b2a":"لا يمكن لتوحيد الشَّرطات أن يختلق وقفة أبدًا: تصبح الشرطة المطبعية <code>—</code> واصلة عادية، واثنتان متتاليتان منها لا تتحولان إلى رمز الوقفة <code> -- </code> الخاص بهذا التطبيق. أما ملف <code>.txt</code> كتبته بوقفات حقيقية فيحتفظ بها.","changelog.90b7cc8211d3":"<strong>علامات الأقسام، مع قائمة انتقال.</strong> كل سطر يبدأ بـ <code>#</code> — <code># Verse 2</code>، <code># Q&amp;A</code> — هو معلَم، وكذلك كل سطر يتكوّن من إحدى كلمات التخطّي لديك (<code>[Chorus]</code>، <code>Bridge</code>). تظهر في قائمة انتقال بجانب شريط التنقل، وتُرسم خطوطًا على الشريط نفسه، ويمرّ عليها <strong>التالي / السابق</strong>. لا شيء لتهيئته، ويصل نص Markdown المستورد وقائمته جاهزة.","changelog.697fb23f904c":"ينتقل «السابق» إلى بداية القسم الذي أنت فيه، ثم إلى ما قبله — كما يتصرف زر المقطوعة السابقة.","changelog.ce1cd4f6f1f3":"<strong>البحث والاستبدال</strong> (<code>Ctrl+F</code>)، ضمن النص المفتوح: عدد مباشر للتطابقات، ومطابقة حالة الأحرف، والكلمات الكاملة فقط، والاستبدال واستبدال الكل. يُضاء التطابق الحالي في المحرر دون أن تخرج كتابتك من مربع البحث، والتراجع عن «استبدال الكل» ضغطة <strong>واحدة</strong> على Ctrl+Z.","changelog.164dc61c0ad5":"<strong>إحصاءات النص</strong>، تحت تقدير زمن القراءة: عدد الكلمات، وعدد المحارف، وتحذير حين يطول سطر بما يكفي ليكون فقرة ملتفّة. والأعداد تخصّ ما <strong>يُؤدّى</strong> فعلًا — إذ تُستبعد التسميات المتخطّاة ورموز الوقفات، فتتفق مع المدة المعروضة بجانبها.","changelog.2a6141e43be0":"التغييرات","changelog.24b7a7366360":"صارت أقسام تقرير التدريب تنقسم عند العلامات إضافةً إلى تسميات التخطّي، فيُتدرَّب على النص المكتوب بعناوين <code>#</code> قسمًا قسمًا دون تهيئة أي كلمات مفتاحية. ويُسمّى القسم من دون زخرفته: <code>[Verse 1]</code> يظهر في التقرير باسم <em>Verse 1</em>.","changelog.8f6fb4eb7f42":"الأمان","changelog.9dc7532525e8":"يعمل كل محلّل للمستندات في <strong>عملية منفصلة</strong>. ثلاث من الصيغ الخمس تقرؤها حزم من أطراف خارجية من ملف لم يكتبه التطبيق، وبُنى الإصدار تتوقف فورًا عند أي خطأ فادح — فلولا ذلك لأسقط ملف PDF تالف الملقّنَ في منتصف القراءة. كما يمنح ذلك العملَ حدًّا زمنيًا ويُبقي ذاكرة المحلّل الجامح خارج التطبيق.","changelog.bbb6d70966f6":"يُنشأ الملف المؤقت للاستيراد في مجلد جديد باسم لا يمكن تخمينه، وعلى أنظمة Unix في مجلد لا يدخله إلا مالكه.","changelog.0fdcda0b6a1e":"<span class=\"release__meta\"><span class=\"release__ver\">v1.3.0</span></span><span class=\"release__title\">3 أغسطس 2026</span>","changelog.4245679cbf6a":"القراءة وفق التوقيت — والكلمات التي لا ينبغي أن تُحتسب.","changelog.3a8bc8eb9047":"<strong>انقر الإيقاع، فيتعلّم التطبيق إيقاعك.</strong> لطالما تحوّل BPM إلى سرعة قراءة عبر رقم واحد: كم حرفًا تقطع في الضربة. كان ذلك تخمينًا — التخمين نفسه لمغنّي الأغاني الهادئة ولمؤدّي الراب، وبينهما فارق بمرتبة عشرية كاملة. صار قسم <strong>الإعدادات ← التوقيت</strong> يتيح لك الآن أن تنقر مع الإيقاع الذي تؤدي به فعلًا، ويقيس ذلك الرقم من سرعة قراءتك أنت بدلًا من افتراضه.","changelog.b94cb35d22f5":"المعايرة التي تُخرج جزءًا من النطاق الموسيقي عن متناول المحرّك <strong>تُضيّق النطاق الذي يعرضه مربع BPM</strong> بدلًا من أن تعرض عليك أرقامًا سيغيّرها في صمت من تحتك.","changelog.4b0c4241773f":"<strong>مترونوم.</strong> نقرة اختيارية على كل ضربة أثناء تمرير النص، مشدَّدة على الضربة الأولى من المازورة، ويؤدي العدّ التنازلي للبدء دور العدّ التمهيدي لها. يولّدها التطبيق بنفسه — فلا ملف صوتي في المثبّت ولا يُجلب أي شيء. وتُجدوَل على ساعة الصوت انطلاقًا من رقم كل ضربة، فلا تنحرف عن التمرير: عند القياس على قراءة مدتها عشر دقائق بأسرع إيقاع يتيحه التطبيق، تبقى النقرة الأخيرة دقيقة تمامًا.","changelog.a0c53f6c5b09":"<strong>عدّاد للمازورات والضربات</strong>، بجانب سطح القراءة، مع <strong>خطوط المازورات مرسومة على شريط التنقل</strong> — فتصبح «ست عشرة مازورة» شيئًا تراه بدلًا من شيء تعدّه في رأسك. ولا يظهر أيٌّ منهما إلا حين تعمل وفق إيقاع.","changelog.84aa1a93cd53":"<strong>وضع التدريب، مع تقرير للتوقيت.</strong> اقرأ النص حتى نهايته فيخبرك التطبيق، قسمًا قسمًا، بما كان ينبغي أن يستغرقه مقابل ما استغرقه فعلًا، ويعرض عليك الوتيرة التي أدّيته بها حقًا. وهو يسجّل <strong>التوقيتات ولا شيء غيرها</strong> — فلا ميكروفون فيه ولا أي مسار للصوت إطلاقًا، وهذا ما يؤكده اختبار، لا مجرد وعد هنا.","changelog.3bcd3e611ff3":"<strong>تحذير هادئ من الوتيرة</strong> أثناء التدريب، ما إن تنحرف القراءة عن خطتها بأكثر من بضع ثوانٍ — فيظهر القسم الذي يتجاوز وقته قبل النهاية لا بعدها.","changelog.440434188c4b":"<strong>كلمات تقرؤها لكنك لا تؤديها.</strong> ضع «اللازمة» أو «المقطع» أو «الجسر» في <strong>الإعدادات ← التوقيت</strong>، فالسطر الذي لا يحوي سوى إحداها — <code>Chorus</code>، <code>[Verse 1]</code>، <code>## Bridge</code> — <strong>لا يكلّف أي وقت على الإطلاق</strong>، فتبقى كلماتك على المازورة التي كتبتها لها. والكلمة نفسها داخل سطر حقيقي لا تتخطى إلا نفسها، فيحتفظ «لنعد إلى اللازمة الآن» بتوقيته. وتبقى ظاهرة على الشاشة باهتة، ولا تنطقها القراءة بصوت عالٍ أبدًا.","changelog.c06854290d9c":"<span class=\"release__meta\"><span class=\"release__ver\">v1.2.0</span></span><span class=\"release__title\">2 أغسطس 2026</span>","changelog.b16edf96208e":"زر التسجيل، وما يحدث للكلمات بعد أن تقولها.","changelog.e03e88337492":"<strong>زر التسجيل زرٌّ، لا جملة.</strong> صار الآن دائرة في داخلها رمز — <strong>●</strong> للتسجيل، و<strong>■</strong> للإيقاف — والتعليمات بجانبه لا داخله، فلم يعد عرض عنصر التحكم يتغيّر وأنت تستخدمه. ولونه يتبع مؤشرك كما يتبع حالته: مرّر المؤشر فوق زر التسجيل فيصبح أخضر، وأثناء التسجيل يصبح أحمر حين تمرّر المؤشر فوقه. وإبعاد المؤشر يعيده كما كان دون أن يغيّر ما سيفعله.","changelog.f7a0e2da64e7":"<strong>صارت الكلمات المُملاة تمرّ عبر المحرر</strong>، وهو المكان الذي كان ينبغي أن تمرّ به دائمًا. وتترتب على ذلك ثلاثة أمور، كان كلٌّ منها عيبًا حقيقيًا من قبل:","changelog.8e6453161785":"<strong>التراجع يستعيد شيئًا واحدًا قلته</strong>، لا الجلسة كلها. كان Ctrl+Z يقفز فوق كل ما أمليته في خطوة واحدة.","changelog.c4b4bb124914":"<strong>يُحتفظ بالنص الذي تكتبه أثناء التسجيل.</strong> كان ما تقوله بعده يُكتب فوقه.","changelog.f9033b43c6e5":"<strong>تحطّ الكلمات حيث يكون مؤشرك</strong>، لا في نهاية النص دائمًا.","changelog.d766eb074a43":"كان الإملاء يُعلن جاهزيته متى وُجد <strong>مجلد</strong> نموذج الكلام، حتى لو كان النموذج داخله مفقودًا أو منسوخًا نصفُه — فيضع على الشاشة زر تسجيل لا يمكنه إلا أن يفشل عند الضغط عليه. وصار الآن يتحقق من الملف الوحيد الذي لا يستطيع محرّك التعرّف على الكلام أن يبدأ من دونه.","changelog.4b11a58f4f52":"في التثبيت على <strong>وحدة تخزين بلا حرف محرك أقراص</strong> (قرص مركَّب في مجلد)، كان مسار النموذج المُمرَّر إلى محرّك التعرّف على الكلام يتحوّل إلى مسار لا يشير إلى أي شيء على الإطلاق. وصار الآن يشير إلى النموذج. أما هل يحمّله محرّك التعرّف بعد ذلك فأمر لم يُختبر على إعداد كهذا — لكن الفشل هناك يذكر النموذج الذي تعذّر فتحه، بدلًا من البحث بصمت في مكان آخر تمامًا.","changelog.c0965fe505ea":"كان النص المُدرَج والمؤشر في <strong>أعلى</strong> النص تمامًا قد يحطّ في أسفله بدلًا من ذلك. لم يكن المحرر قادرًا على قراءة موضع مؤشر يقع على النص ككل لا داخل أحد أسطره، فكان يجيب بطول النص كله — فيذهب اللصق، أو السطر المُملى، إلى النهاية.","changelog.15f80b1047f4":"كان الإملاء قد يُعلن أنه <strong>غير متاح بينما نموذج سليم تمامًا مثبَّت</strong>: إذ كان مجلد <code>vosk-model-en</code> شارد أو منسوخ نصفُه في مجلد بياناتك يُفضَّل على النموذج الموجود داخل التطبيق، ثم يُرفض لأنه غير مكتمل. وصار التطبيق الآن يتجاوز المجلد غير الصالح للاستخدام ويستخدم النموذج الذي يأتي معه.","changelog.4ecc1ea9414e":"<code>npm run dev:vosk</code> للمساهمين — تشغيل تطويري يستطيع الإملاء فعلًا. فالإملاء في غير ذلك مقصور على بنى الإصدار، مما جعل العمل عليه مُربكًا.","changelog.9ef45f3d9beb":"صار البحث في موقع التوثيق يجد <strong>الإملاء</strong> — فقد صدرت الميزة في 1.1.0 ولم تكن في الفهرس، فكان البحث عنها لا يُرجع شيئًا. وفي الاتجاه المعاكس، اختفت نتائج البحث التي لم يكن بوسعها إلا أن تنتهي بالخطأ 404: فقد كان الفهرس المشترك يذكر خمسة تطبيقات من Freally ليس لها موقع بعد، وهو ما شكّل 39 من مُدخلاته البالغة 109.","changelog.1569fac6a9e5":"يسجّل <code>THIRD-PARTY.md</code> الآن <strong>Vosk</strong> (المحرّك والنموذج وبيئة تشغيل MinGW الخاصة بـ Windows) إلى جانب الخطوط؛ ويحمل <code>NOTICE</code> الآن الإشارات إلى الشيفرة المصدرية المقابلة لبيئة التشغيل تلك. ويأتي الملفان كلاهما داخل المثبّت.","changelog.a02b0fb176eb":"توضح ملاحظة الإملاء في الإعدادات ما يحدث حين تكون <strong>المزامنة الشبكية</strong> مفعّلة: يصل النص المُملى إلى مشاهديها فور كتابته، تمامًا كالكتابة.","changelog.226b619dcadb":"<span class=\"release__meta\"><span class=\"release__ver\">v1.1.0</span></span><span class=\"release__title\">2 أغسطس 2026</span>","changelog.d3ca2e44459c":"طريقة واحدة لاستخدام صوتك، تعمل لحظة تفعيلها.","changelog.b370d746f358":"<strong>اكتب نصك بالكلام</strong> (FT-33) — فعِّل <strong>الإملاء</strong> في الإعدادات ← الصوت فيظهر زر تسجيل فوق النص. اضغطه فيُكتب ما تقوله؛ واضغطه مرة أخرى للإيقاف.","changelog.e02d4e39e7e3":"لا يحتاج إلى تدريب ولا إلى إعداد: يأتي نموذج الكلام داخل المثبّت، فيعمل لحظة تفعيله. لا يُنزَّل شيء أثناء التشغيل ولا يُرسَل شيء إلى أي مكان — فمحرّك التعرّف على الكلام ونموذجه على جهازك، ويظل ذلك صحيحًا دون اتصال. والميكروفون مفتوح أثناء التسجيل فقط، ولا يُكتب شيء مما تقوله في ملف سوى النص نفسه.","changelog.4118fb4fed0e":"المحذوفات","changelog.9201332ddf55":"<strong>أُزيلت الأوامر الصوتية.</strong> كانت تتطلب منك أن تسجّل كل أمر — تشغيل، إيقاف مؤقت، أسرع، أبطأ، الوقفة التالية، العودة إلى البداية — بصوتك قبل أن يفعل أيٌّ منها شيئًا، ثم أن تُبقي زرًا مضغوطًا أثناء الكلام. وإلى أن تُنجز ذلك التسجيل، كان الضغط المستمر على الزر يفتح الميكروفون ولا يحقق شيئًا على الإطلاق، دون أي طريقة لتمييز ذلك عن عطل. والإملاء يغطي المجال نفسه دون أي شيء يحتاج إلى تدريب.","changelog.8afda10a9120":"<strong>أُزيلت ميزة «تابِع قراءتي»</strong> للسبب نفسه: طريقة واحدة واضحة لاستخدام صوتك خير من ثلاث متداخلة. ولا يزال عمل المحاذاة الذي كان وراءها موجودًا كمكتبة، وقد يعود في شكل مختلف.","changelog.119dd324728e":"صارت المثبّتات أكبر من مثبّتات 1.0.0 بما يتناسب مع ذلك — فنموذج الكلام يبلغ نحو 40 ميغابايت، ويأتي الآن سواء استخدمته أم لا.","changelog.9133884e4863":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0</span></span><span class=\"release__title\">2 أغسطس 2026</span>","changelog.3d6b5cab67c7":"أول إصدار منشور: كل ما جاء في المرحلة 3 (التحكم الصوتي دون استخدام اليدين) وجولة التحسين في المرحلة 5، مُصدَرًا كمثبّتات موقَّعة لـ Windows وmacOS وLinux.","changelog.880aaef19013":"<strong>جولة ترحيبية مدتها دقيقة واحدة</strong> (FT-50) — في أول مرة تفتح فيها التطبيق، تعرّفك أربع خطوات قصيرة بالمحرر وعلامات الوقفات فيه، وبأدوات ضبط الوتيرة، وبجهاز العرض. تخطَّها في أي لحظة، وشغّلها مجددًا متى شئت من <strong>الإعدادات ← عام ← أعد عرض الجولة</strong>.","changelog.0df57f3fd77c":"<strong>سمة تتبع نظامك</strong> (FT-50) — إلى جانب «داكن» و«فاتح» صار هناك الآن <strong>مثل نظامي</strong>، الذي يتبدّل مع نظام التشغيل ويعيد رسم الواجهة فورًا حين يتغيّر جهازك عند الغروب. ولا يزال «داكن» هو الافتراضي.","changelog.3d5dfaad60e5":"<strong>الأوامر الصوتية</strong> (FT-30، FT-31) — درّب <strong>تشغيل، إيقاف مؤقت، أسرع، أبطأ، الوقفة التالية، العودة إلى البداية</strong> بصوتك (بضعة تسجيلات لكلٍّ منها) وتحكّم في الملقّن دون استخدام يديك. يظهر مؤشر <strong>● جارٍ الاستماع</strong> كلما كان الميكروفون مفتوحًا؛ اختر <strong>اضغط للتحدث</strong> (الميكروفون مفتوح فقط ما دمت تضغط زرًا) أو <strong>الاستماع الدائم</strong>. <strong>معطّلة افتراضيًا.</strong> بلا نموذج: تُطابَق بمعالجة إشارة كلاسيكية مع تسجيلاتك أنت، على الجهاز.","changelog.689534aed982":"<strong>تتبّع الصوت</strong> (FT-32، FT-34، FT-35) — وضع <strong>اختياري</strong> يمرّر النص ليواكبك وأنت تقرؤه بصوت عالٍ، متعرّفًا على كلمات النص نفسه بنموذج Vosk مرفق بترخيص Apache-2.0. وهو <strong>يتنحّى للتحكم اليدوي</strong> لحظة أن يفقد موضعك (فلا يمرّر النص أبدًا إلى مكان خاطئ) ولا يتحكم إلا في معاينة المشغّل، لا في جهاز العرض أبدًا. <strong>معطّل افتراضيًا</strong>، ويظهر باهتًا مع ذكر السبب حيث لا يكون النموذج مثبَّتًا. وطبقة المحاذاة الحتمية التي تحدد موضعك في النص مملوكة بالكامل ومغطّاة باختبارات الوحدات.","changelog.10a2d92eba51":"<strong>مثبّتات موقَّعة وذاتية التحديث</strong> (FT-51، FT-52) — لـ Windows (<code>.exe</code> و<code>.msi</code>)، وملف <code>.dmg</code> شامل لـ macOS، وAppImage و<code>.deb</code> لـ Linux، وكلها مبنية من إيداع واحد موسوم. يتحقق المحدِّث المدمج في التطبيق من صفحة الإصدارات، ويُتحقَّق من كل تحديث مقابل مفتاح توقيع يحمله التطبيق — والتحديث الذي لا يمكن التحقق منه يُرفض بدلًا من تثبيته.","changelog.6831bb79a881":"<strong>جولة لإمكانية الوصول عبر لوحة المفاتيح وقارئات الشاشة</strong> (FT-50) — صار كل عنصر تحكم قابل للتركيز يُظهر حلقة تركيز واضحة؛ ويبقى <strong>Tab</strong> داخل مربع الحوار المفتوح بدلًا من أن يتيه إلى النافذة التي خلفه؛ وإغلاق مربع الحوار يعيد التركيز إلى الزر الذي فتحه؛ وصارت قائمة فئات الإعدادات تُعلن اللوحة التي تنظر إليها فعلًا، حتى أثناء تصفيتها بالبحث. كما يحترم التطبيق <strong>تقليل الحركة</strong> في كل مكان. أما تمرير النص نفسه فقد تُرك عمدًا دون أن يمسّه هذا الإعداد — فهو الغاية التي وُجد التطبيق من أجلها، وأنت تتحكم في سرعته مباشرة أصلًا.","changelog.54a57c3147c4":"الخصوصية","changelog.deae17e358ff":"<strong>لا شبكة، أبدًا.</strong> لا تلمس الأوامر الصوتية الشبكة ولا القرص أبدًا — يُطابَق الصوت في الذاكرة مع تسجيلاتك أنت، ولا يُكتب شيء مما تقوله في ملف. ويشغّل تتبّع الصوت محرّك التعرّف على الكلام بالكامل على الجهاز؛ والنموذج يأتي في المثبّت ولا يُنزِّل شيئًا أثناء التشغيل.","changelog.0d7048033eef":"_<strong>تتبّع الصوت غير قابل للاستخدام في هذا البناء.</strong> يحتاج محرّك التعرّف على الكلام إلى نموذج كلام، وهذا الإصدار لا يتضمّن واحدًا بعد — فتكتشف الميزة ذلك وتُعلن أنها غير متاحة مع ذكر السبب، بدلًا من أن تفشل حين تفعّلها. أما <strong>الأوامر</strong> الصوتية فلا تتأثر: إذ لا تحتاج إلى نموذج وتعمل هنا. وطبقتا المحاذاة والقواعد اللتان تحتها مكتملتان ومُختبرتان._","changelog.f8a8681a3de9":"<span class=\"release__meta\"><span class=\"release__ver\">v0.300.0</span></span><span class=\"release__title\">22 يوليو 2026</span>","changelog.49b18dafa9ac":"إكمال تلقائي دون اتصال في محرر النصوص: يقترح بقية الكلمة وأنت تكتب، بأيٍّ من اللغات الثماني عشرة، من قوائم كلمات تأتي داخل التطبيق.","changelog.863ad5535d5a":"<strong>إكمال تلقائي بنص شبحي</strong> (FT-20، FT-21) — ابدأ كلمة فتظهر بقيتها باهتة أمام المؤشر. <strong>Tab</strong> يقبلها، و<strong>Esc</strong> يرفضها، والاستمرار في الكتابة يتجاهلها. ويُكمل عبارات شائعة كاملة أيضًا، بعد أن تُنهي كلمة وتضغط مفتاح المسافة.","changelog.342d77799f0d":"<strong>إعدادات الإكمال التلقائي</strong> — لوحة <strong>المحرر</strong> جديدة فيها مفتاح تشغيل وإيقاف و<strong>لغة اقتراحات</strong> خاصة بها، منفصلة عن لغة التطبيق، لأن كتابة نص بلغة بينما يعمل التطبيق بلغة أخرى أمر طبيعي.","changelog.bf3195662b89":"<strong>جداول كلمات وعبارات للغات الثماني عشرة كلها</strong> (FT-22) — نحو 464,000 كلمة و345,000 عبارة إجمالًا، مضمَّنة في المثبّت. لا تُحمَّل إلا اللغة التي تستخدمها فعلًا، فلا يكلّف ذلك التطبيق سوى نحو 0.5 ميغابايت من الذاكرة في المرة الواحدة بدلًا من الـ 12 ميغابايت كلها.","changelog.9fb2fa59ae13":"<strong>صار منتقي اللغة يبدأ بالإنجليزية ثم يتسلسل أبجديًا حسب اسم كل لغة بلغتها</strong> — Deutsch وEspañol وFrançais وهكذا — ويبقى على هذا الترتيب أيًّا كانت لغة التطبيق. كان سابقًا يتبع الأسماء الإنجليزية، فكان الترتيب يتغيّر بحسب ما اخترته.","changelog.6e805db44ddd":"<strong>الإكمال التلقائي لا يلمس الشبكة أبدًا.</strong> إنه بحث في جداول داخل المثبّت — بلا نموذج، ولا خدمة، ولا قياس عن بُعد. لا يُرسَل شيء مما تكتبه إلى أي مكان، وتعمل الميزة والجهاز غير متصل بالإنترنت.","changelog.97775eaa1065":"<span class=\"release__meta\"><span class=\"release__ver\">v0.200.0</span></span><span class=\"release__title\">21 يوليو 2026</span>","changelog.fdaeb02ed57c":"الملقّن المستقل: نصوص يمكنك الاحتفاظ بها، وجهاز عرض للمقدّم، وأزرار تشغيل حقيقية، وملقّن يقرأ نفسه بصوت عالٍ.","changelog.3c1c1f577fc6":"<strong>مكتبة النصوص</strong> (FT-10) — ملفات <code>.ftscript</code> يمكنك إنشاؤها وفتحها وإعادة تسميتها وحذفها، مع قائمة بالأحدث و<strong>حفظ تلقائي</strong> أثناء الكتابة. وهي نص UTF-8 عادي في مجلد واحد، فيبقى النص قابلًا للقراءة والمقارنة والإنقاذ في أي محرر نصوص إن اختفى هذا التطبيق يومًا. ويعيد التطبيق فتح آخر ما كان مفتوحًا لديك.","changelog.54ba591e950e":"<strong>شارات الوقفات في المحرر</strong> (FT-11) — كل <code> -- </code> / <code> --2 </code> داخل السطر يُعرض كشارة ذرّية تُظهر طول الوقفة. لا يمكن لمؤشر الكتابة أن يقف إلا قبلها أو بعدها، ويحذف Backspace/Delete الرمز كاملًا بضغطة واحدة، ويحدده Shift مع أحد الأسهم كوحدة واحدة، ويحمل النسخ/القص نص <code> -- </code> الحقيقي، ويُصحَّح التباعد غير المتّسق في النص الملصوق. وكتابة الشرطة الثانية تُنشئ لك وقفة.","changelog.b9587c13e3c6":"<strong>نافذة جهاز العرض</strong> (FT-12) — افتح سطح القراءة على أي شاشة متصلة، ليملأها من الحافة إلى الحافة، مع <strong>قلب مرآوي</strong> لزجاج التلقين المقسّم للأشعة. وهي تعمل من حالة التمرير نفسها التي تعمل منها معاينة المشغّل، فلا يمكن أن تختلفا أبدًا على موضع القراءة، ولها أزرار تشغيلها وشريط تنقلها واختصارات لوحة مفاتيحها الخاصة لمن يقرأ فعلًا.","changelog.d50b42582cf9":"<strong>المزامنة الشبكية</strong> (FT-12) — اعرض النص المتحرك على هاتف أو جهاز لوحي أو حاسوب محمول ثانٍ على شبكتك أنت، عبر رابط ورمز QR يعرضهما عليك التطبيق. يضبط كل جهاز حجم خطه الخاص دون أن يغيّر ما يراه أي شخص آخر. <strong>معطّلة افتراضيًا</strong>، ومقصورة على هذا الحاسوب وحده حتى تفتحها للشبكة صراحةً، ومحمية بمفتاح يُولَّد من جديد في كل تشغيل، و<strong>للقراءة فقط</strong> — لا شيء يرسله المتصفح يمكنه تغيير التمرير أو النص أو أي إعداد.","changelog.00b57b5822cd":"<strong>أزرار تشغيل حقيقية</strong> (FT-13) — تشغيل / إيقاف مؤقت / إيقاف / إرجاع / تقديم سريع كأزرار SVG حقيقية مع <strong>التكرار بالضغط المستمر</strong>، وشريط تنقل على طريقة YouTube يعرض زمن القراءة المنقضي والإجمالي (مع احتساب الوقفات)، ومعاينة الكلمات عند أي نقطة بتمرير المؤشر، والبدء بالنقر على كلمة، والتنقل بعجلة الفأرة، واختصارات لوحة المفاتيح على جهاز العرض.","changelog.d3d56659d660":"<strong>وضع سرعة BPM</strong> (FT-14) — اقرأ الوتيرة بالأحرف في الثانية أو بـ <strong>BPM (من 20 إلى 250)</strong> للأداء الموسيقي. يبقى المحرّك قائمًا على الأحرف في الثانية طوال الوقت؛ أما BPM فوضع للعرض والإدخال، وكل قيمة BPM يمكنك كتابتها تقع داخل نطاق المحرّك نفسه بدلًا من أن تُقصّ في صمت من تحتك.","changelog.5fe2620dd908":"<strong>أدوات التحكم في المظهر</strong> (FT-15) — الخط، وسماكته، ولون النص، والهوامش الجانبية، وتباعد الأسطر، و<strong>موضع خط القراءة</strong> على الشاشة. وهي تقيم في المحرّك لا في حالة نافذة واحدة، فتبدو المعاينة وجهاز العرض والمزامنة الشبكية متشابهة دائمًا.","changelog.ca6865582cd0":"<strong>القراءة بصوت عالٍ باستخدام تركيب الكلام الخاص بنظام التشغيل</strong> (FT-16) — دع الملقّن يقرأ لك النص بالوتيرة التي ضبطتها، لتختبر التوقيت بأذنك قبل تصوير اللقطة. يتبع التظليل الكلمة المنطوقة، وتصبح الوقفات صمتًا حقيقيًا (لا يُنطق <code>--</code> أبدًا «شرطة»)، والتنقل يقفز بالكلام. وهي <strong>للمعاينة فقط</strong>: لا تحرّك جهاز عرض المقدّم أبدًا. تستخدم الأصوات الموجودة أصلًا في نظام تشغيلك (Windows OneCore/SAPI، وmacOS AVSpeechSynthesis، وLinux Speech Dispatcher / espeak-ng) — ولا يُرفق أي محرّك كلام.","changelog.cdfbacda0108":"<strong>صارت كل لغة تُعرض الآن، على كل جهاز.</strong> يضمّ التطبيق خطوط Noto للغات الثماني عشرة التي يأتي بها — اللاتينية واليونانية والسيريلية والفيتنامية والعربية والديفناغارية واليابانية والكورية والصينية المبسطة. كان التبديل إلى اليابانية على جهاز لا خط يابانيًا مثبَّتًا عليه يُظهر مربعات بدلًا من الواجهة؛ والآن يحمل التطبيق ما يحتاجه. ولا تُحمَّل إلا مجموعات المحارف التي تستخدمها اللغة المختارة فعلًا، والخطوط تسند كل خطوط القراءة أيضًا، فلا يمكن لاختيار «بزخارف» أن يجعل لغةً غير مقروءة أبدًا. الخطوط مرخّصة بموجب SIL Open Font License؛ ويأتي الإشعار مع التطبيق باسم <code>THIRD-PARTY.md</code>.","changelog.d1589cdefe34":"<strong>يرسم التطبيق نافذته بنفسه.</strong> لا شريط عنوان من نظام التشغيل: عنوان في المنتصف، مع الإعدادات وحول، والتصغير / التكبير والاستعادة / الإغلاق على اليمين — الترتيب نفسه الذي يستخدمه Freally Player، فتبدو نوافذ المجموعة متشابهة. الشريط قابل للسحب، والنقر المزدوج لا يزال يكبّر النافذة، ولا يزال تغيير حجم النافذة ممكنًا من كل حافة وزاوية.","changelog.83b865a057ab":"<strong>صارت الإعدادات مربع حوار إعدادات حقيقيًا</strong>، على شاكلة إعدادات Freally Capture: شريط جانبي للفئات (عام، القراءة، المظهر، جهاز العرض، الشبكة) مع مربع بحث، وتذييل فيه <strong>موافق / إلغاء / تطبيق</strong>. يبقى «تطبيق» معطّلًا حتى يتغيّر شيء فعلًا، وتُميِّز نقطةٌ الفئاتِ التي عدّلتها ولم تطبّقها بعد.","changelog.dd1a689ff484":"<strong>التصغير إلى شريط النظام</strong> (الإعدادات ← عام). معطّل افتراضيًا. حين يكون مفعّلًا، يُخفي التصغير النافذة ويضع أيقونة في شريط النظام؛ وتعيد الاستعادة النافذة <strong>وتُزيل الأيقونة</strong> — فالتطبيق إما في شريط المهام وإما في شريط النظام، لا في الاثنين معًا أبدًا. وقائمة شريط النظام مترجمة كبقية التطبيق.","changelog.4124706702a9":"<strong>صارت أيقونة التطبيق هي العمل الفني الكامل بكل الأحجام.</strong> كان <code>0.100.0</code> قد وضع مكانها حرف «F» مقصوصًا وحده للأيقونات بحجم 48 بكسل وما دون، بحجة أن الشعار النصي في العمل الفني لا يُقرأ بهذا الصِّغَر. ثم تبيّن أن علامة واحدة متسقة أهم من علامة مقروءة لكنها مختلفة، فأُلغي القص — وصار شريط المهام وشريط النظام وأيقونة الموقع تُظهر كلها الأيقونة نفسها الآن.","changelog.c347bd2b4305":"ما كشفته جولة المراجعة لهذه المرحلة، قبل الإصدار:","changelog.47424533ef57":"<strong>كانت شارة الوقفة قد تظهر حيث لا يتوقف الملقّن.</strong> كان لكلٍّ من المحرر والقراءة بصوت عالٍ نسخته الخاصة من قواعد <code> -- </code>، من دون الحدود التي يطبّقها محرّك التمرير — فكان <code>--2.5.3</code> يُرسم كوقفة سيتجاوزها الملقّن مباشرة. وصارت الثلاثة الآن تتشارك ماسحًا واحدًا.","changelog.b434155bb7d9":"<strong>كان النقر بزر الفأرة الأيمن على أيقونة شريط النظام يستعيد النافذة</strong> بدلًا من فتح القائمة، مما جعل خيار «إنهاء» في شريط النظام نفسه بعيد المنال.","changelog.ec0cf2fce1a1":"<strong>كانت أزرار اتفاقية التشغيل الأول قد تقع أسفل الحافة السفلية للنافذة</strong> بعد أن صار التطبيق يرسم شريط عنوانه بنفسه.","changelog.9d5731455d75":"<strong>كانت الإعدادات قد تُظهر قيمة لا يستخدمها التطبيق.</strong> فالرقم الذي قصّته الواجهة الخلفية (منفذ أقل من 1024 مثلًا) ظل يُعرض كما كُتب حتى إعادة التشغيل التالية؛ وصار مربع الحوار يُظهر الآن ما خُزِّن فعلًا.","changelog.db89654f4e78":"<strong>كان البحث في الإعدادات قد يترك اللوحة الخطأ على الشاشة</strong>، دون فئة مُبرَزة تفسّر ذلك.","changelog.39ed54f3671f":"<strong>صار الإيقاف إجراءً واحدًا في المحرّك</strong> بدلًا من ثنائي إيقاف مؤقت وإرجاع يركّبه كل زر بنفسه، فيتصرف كل ما يوقف التمرير بالطريقة نفسها.","changelog.e806a291cfc3":"الاختبار","changelog.b6521470f6ed":"<strong>صار Playwright يغطي كل ميزة من ميزات المرحلة 1 يستطيع الوصول إليها</strong> — دورة حياة مكتبة النصوص كاملة، وسلوك الشارات، ومنتقي الشاشة، وأزرار التشغيل، وتحويل BPM، ومسار المظهر، والعقد القاضي بأن القراءة بصوت عالٍ لا تلمس التمرير المشترك أبدًا. ويسجّل الجسر المُحاكى استدعاءات الاتصال بين العمليات، فتتحقق الاختبارات مما طلبته الواجهة فعلًا من الواجهة الخلفية.","changelog.965a9f5ce8e2":"<strong>صار التطبيق يُشغَّل وتُلتقط له صورة على Windows وmacOS وLinux في كل تشغيل لـ CI</strong> (<code>scripts/app-screenshot.mjs</code>)، ويفشل التشغيل إن مات التطبيق عند البدء أو لم يرسم شيئًا. فنجاح التصريف شيء، وعرض واجهة الويب المضمّنة لشيء فعلًا شيء آخر.","changelog.33678f48d52f":"<strong>تُفحص كل لغة من حيث قابلية القراءة، لا من حيث النصوص فحسب.</strong> يبدّل اختبارٌ التطبيقَ إلى كل لغة من اللغات الثماني عشرة ويُثبت أن كل محرف في واجهتها تغطيه الخطوط المرفقة. فنظام الكتابة الذي لا خط له يُعرض مربعات، تبدو نصًا سليمًا للقطة الشاشة ولكل فحص آخر — فكان من الممكن أن تتعطّل العربية والهندية واليابانية والكورية والصينية كلٌّ منها في صمت، ولمن يقرؤونها وحدهم.","changelog.503e7e57035d":"<strong>صارت الترجمة التي ترتدّ إلى الإنجليزية في صمت تُفشل البناء.</strong> فجولات الترجمة الجماعية تترك الإنجليزية وراءها في كل ما لا تستطيع ترجمته، وتُحلَّل النتيجة وتُشحن وكأنها مكتملة. أما الاستثناءات الحقيقية — «OK» و«Port» وأسماء العلم — فمُدرجة مع ذكر السبب.","changelog.8b79c1c1b492":"<strong>صار العرض على Linux مُثبَتًا لا مفترضًا.</strong> تُلتقط صورة الشاشة في CI داخل حاوية بمُصيِّر برمجي، لأن مشغّل Linux المجرّد على GitHub لا يملك GL عاملًا وكان ينتج نافذة فارغة سواء كان التطبيق سليمًا أم لا — والفحص الذي لا يمكن أن يفشل لم يكن يخبرنا بشيء.","changelog.bf256044a419":"كل ما لا يمكن أتمتته حقًا — شاشة ثانية، وزجاج التلقين، والكلام المسموع، وهاتف على شبكة Wi-Fi لديك — صارت له الآن <strong>تمارين خطوة بخطوة</strong> في <code>Live-To-Do-List.md</code>.","changelog.8a7525b1492f":"ملاحظات","changelog.f38acbd9b28b":"<strong>لا يزال بلا ذكاء اصطناعي، ولا حسابات، ولا قياس عن بُعد.</strong> تقدّم المزامنة الشبكية نصك إلى الأجهزة التي توجّهها إليها، على شبكتك أنت؛ ولا يُرفع شيء ولا يُمرَّر عبر وسيط. ويبقى الطلب الصادر الوحيد الذي يجريه التطبيق هو التحقق من التحديثات.","changelog.aadc02e8de62":"<span class=\"release__meta\"><span class=\"release__ver\">v0.100.0</span></span><span class=\"release__title\">21 يوليو 2026</span>","changelog.7bfe7961d71b":"مرحلة الهيكل الأولي: صار التطبيق يُبنى ويعمل ويشترط قبول الاتفاقية، مع محرّك التمرير القائم على الأحرف منقولًا من Freally Capture.","changelog.19bd3024e088":"<strong>هيكل Tauri v2 الأولي</strong> (FT-00) — مساحة عمل Rust (<code>src-tauri</code>) إلى جانب واجهة React/TypeScript (<code>ui</code>)، تتشارك بنية أدوات Freally Capture: <code>ci.yml</code> و<code>scripts/ci-local.mjs</code> و<code>deny.toml</code> و<code>rust-toolchain.toml</code> مثبَّت الإصدار، فيشغّل <code>npm run ci:local</code> البوابة كاملة منذ اليوم الأول.","changelog.045988032f64":"<strong>مجموعة الأيقونات</strong> (FT-01) — مولَّدة من العمل الفني المصدر بواسطة <code>scripts/make-icons.py</code>، لـ Windows وmacOS وLinux إضافةً إلى أيقونات الموقع. تستخدم الأحجام البالغة 48 بكسل وما دونها نسخة <strong>الحرف «F» وحده</strong>، لأن الشعار النصي المدمج في العمل الفني لا يُقرأ تحت 64 بكسل (بالقياس، لا بالتخمين).","changelog.e0471332722d":"<strong>محرّك الملقّن القائم على الأحرف</strong> (FT-02) — <code>teleprompter.rs</code> وتوأمه بلغة TypeScript <code>ui/src/lib/caesura.ts</code>، منقولان من Freally Capture: إزاحات تمرير بالأحرف المرئية، ووقفات <code> -- </code> داخل السطر (<code> --2 </code> لوقفة بمدة مخصصة)، وأدوات للتنقل والخطوة والسرعة، وعدّ تنازلي قبل البدء. تضع المعاينة وجهاز العرض النص على مسرح واحد ثابت العرض ثم تغيّر مقياسه بـ CSS، فيلتفّ السطر عند العمود نفسه تمامًا.","changelog.a1b0c9f8ea89":"<strong>هيكل التطبيق بنافذة واحدة</strong> (FT-03) — شريط الأدوات، وإدخال النص، وسطح الملقّن الحي، مع <strong>الإعدادات</strong> على نمط المسودّة والتطبيق (لا يسري شيء حتى «تطبيق»؛ و«إلغاء» يعيد بالضبط ما كان لديك) وأساس تدويل مبني على Fluent يدعم <strong>18 لغة</strong>.","changelog.b45c55ac02ea":"<strong>موقع التوثيق + سجل التغييرات</strong> (FT-04) — يُقدَّم الموقع عبر GitHub Pages من <code>/docs</code>، على غرار تطبيقات Freally الأخرى.","changelog.8b96bdf6151d":"<strong>بوابة اتفاقية الترخيص عند التشغيل الأول</strong> (FT-05) — لا يمكن استخدام التطبيق حتى تُقبل الاتفاقية. والقبول مرتبط برقم إصدار و<strong>محفوظ عبر كل حفظ للإعدادات</strong> (وهو خطأ صدر في Freally Capture؛ وله الآن اختبار انحدار).","changelog.d5361112a7c1":"<strong>مُبلِّغ المشكلات والتحقق من التحديثات</strong> — مُبلِّغ الأعطال المعتمد في Havoc (تقرير محلي منقّى من البيانات الحساسة، وإشعار أصلي بأنه «توقّف بشكل غير متوقع»، وإعادة تشغيل، وإرسال عبر GitHub أو Gmail أو البريد تبادر به أنت بنفسك) وتحقق من التحديثات عند التشغيل يعرض الإصدار وملاحظات الإصدار الحقيقية قبل فعل أي شيء.","changelog.198e4f9204b8":"<strong>بلا ذكاء اصطناعي، ولا حسابات، ولا قياس عن بُعد.</strong> الطلب الصادر الوحيد هو التحقق من التحديثات؛ ولا يرسل شيئًا عنك ولا عن جهازك ولا عن نصوصك.","changelog.04d59a3b7905":"روابط التنزيل على الموقع مجرد عناصر نائبة حتى يكتمل مسار الإصدار.","changelog.a3c71b90162b":"قيود معروفة","changelog.4d18eba61c3f":"<strong>لا توجد مثبّتات بعد.</strong> <code>0.100.0</code> محطة على مستوى الشيفرة المصدرية؛ أما مسار الإصدار الموقَّع لكل نظام تشغيل فمرحلة لاحقة.","changelog.57871c6e9623":"<strong>التحديثات التلقائية غير مفعّلة.</strong> يأتي المحدِّث دون المفتاح العام للتوقيع، فيرفض كل حزمة بدلًا من تثبيت حزمة لم يُتحقَّق منها — إنه يفشل بأمان، لكنه لا يستطيع النجاح أيضًا. وسيُبلغ «التحقق من التحديثات» عن خطأ حتى يكتمل توقيع الشيفرة."};
